--
-- Name: audit_inventory_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.audit_inventory_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_delta integer;
  v_reason text;
BEGIN
  IF OLD.qty IS NOT DISTINCT FROM NEW.qty THEN
    RETURN NEW;
  END IF;

  v_delta := NEW.qty - OLD.qty;

  v_reason := NULLIF(trim(current_setting('app.movement_reason', true)), '');
  v_reason := COALESCE(v_reason, 'Ajuste automático de auditoría');

  -- Dejar explícito en el motivo si es aumento o disminución (trazabilidad absoluta)
  IF v_delta > 0 THEN
    v_reason := v_reason || ' - Aumento';
  ELSIF v_delta < 0 THEN
    v_reason := v_reason || ' - Disminución';
  END IF;

  SELECT id INTO v_user_id
  FROM public.users
  WHERE auth_user_id = auth.uid()
  LIMIT 1;

  IF v_user_id IS NULL THEN
    SELECT id INTO v_user_id
    FROM public.users
    WHERE company_id = NEW.company_id AND role = 'admin'
    ORDER BY created_at
    LIMIT 1;
  END IF;

  IF v_user_id IS NULL THEN
    RETURN NEW;
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.inventory_movements
    WHERE product_id = NEW.product_id
      AND (store_from_id = NEW.store_id OR store_to_id = NEW.store_id)
      AND created_at > now() - interval '1 second'
  ) THEN
    RETURN NEW;
  END IF;

    company_id,
    product_id,
    store_from_id,
    store_to_id,
    type,
    qty,
    old_qty,
    new_qty,
    user_id,
    reason
  ) VALUES (
    NEW.company_id,
    NEW.product_id,
    NULL,
    NEW.store_id,
    'ADJUST',
    v_delta,
    OLD.qty,
    NEW.qty,
    v_user_id,
    v_reason
  );

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION audit_inventory_change(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.audit_inventory_change() IS 'Registra en inventory_movements. Usa app.movement_reason si existe (ej. Ajuste manual almacén). Añade " - Aumento" o " - Disminución" al motivo para trazabilidad absoluta.';


