-- Name: FUNCTION create_product_v3(p_sku text, p_barcode text, p_name text, p_category text, p_cost_usd numeric, p_sale_price_usd numeric, p_tax_rate numeric, p_store_inventories jsonb); Type: COMMENT; Schema: public; Owner: -
