COMMENT ON FUNCTION public.create_product_v3(p_sku text, p_barcode text, p_name text, p_category text, p_cost_usd numeric, p_sale_price_usd numeric, p_tax_rate numeric, p_store_inventories jsonb) IS 'Crea un producto con inventario en todas las tiendas activas. Requiere: name, sku, category no vacíos; cost_usd y sale_price_usd > 0.';


--
-- Name: create_product_with_inventory(uuid, text, text, numeric, text, numeric, text, numeric, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_product_with_inventory(p_company_id uuid, p_barcode text, p_category text, p_cost_usd numeric, p_name text, p_sale_price_usd numeric, p_sku text, p_tax_rate numeric, p_store_inventories jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    new_product_id UUID;
    inventory_item JSONB;
    v_qty NUMERIC;
BEGIN
    -- 1. Insertar el Producto en la tabla 'products'
        company_id, barcode, category, cost_usd, name, sale_price_usd, sku, tax_rate
    ) VALUES (
        p_company_id, p_barcode, p_category, p_cost_usd, p_name, p_sale_price_usd, p_sku, p_tax_rate
    ) RETURNING id INTO new_product_id;

    -- 2. Procesar el Inventario por Tienda
    FOR inventory_item IN SELECT * FROM jsonb_array_elements(p_store_inventories)
    LOOP
        v_qty := COALESCE((inventory_item->>'qty')::NUMERIC, 0);
        
        -- Si la cantidad es negativa, la Base de Datos la rechazará (por el CHECK constraint)
        
            company_id, store_id, product_id, qty, min_qty
        ) VALUES (
            p_company_id,
            (inventory_item->>'store_id')::UUID,
            new_product_id,
            v_qty,
            COALESCE((inventory_item->>'min_qty')::NUMERIC, 0)
        ) ON CONFLICT (company_id, store_id, product_id) 
          DO UPDATE SET qty = EXCLUDED.qty; -- Usa UPSERT para actualizar si ya existe (por si acaso)
    END LOOP;

    RETURN jsonb_build_object(
        'success', true,
        'product_id', new_product_id,
        'message', 'Producto y stock creados exitosamente.'
    );
EXCEPTION WHEN OTHERS THEN
    RAISE EXCEPTION 'Error creando producto con inventario: %', SQLERRM;
END;
$$;


--
-- Name: create_user_atomic_admin(text, text, text, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_user_atomic_admin(p_email text, p_password text, p_name text, p_role text, p_company_id uuid, p_assigned_store_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  new_user_id UUID;
BEGIN
  -- Validar que el email no exista en public.users
  IF EXISTS (SELECT 1 FROM users WHERE email = p_email) THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'El correo electrónico ya está registrado en el sistema'
    );
  END IF;

  -- Validar que el rol sea válido
  IF p_role NOT IN ('admin', 'manager', 'cashier') THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Rol inválido. Debe ser: admin, manager o cashier'
    );
  END IF;

  -- Validar que manager tenga tienda asignada
  IF p_role = 'manager' AND p_assigned_store_id IS NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'El rol de Gerente requiere una tienda asignada'
    );
  END IF;

  -- Crear SOLO el perfil en public.users (sin auth_user_id)
  -- El auth_user_id se vinculará cuando el usuario se registre
    auth_user_id, -- NULL inicialmente
    company_id,
    email,
    name,
    role,
    assigned_store_id,
    active,
    created_at,
    updated_at
  ) VALUES (
    NULL, -- Se vinculará cuando el usuario se registre
    p_company_id,
    p_email,
    p_name,
    p_role,
    CASE 
      WHEN p_role = 'admin' THEN NULL 
      ELSE p_assigned_store_id 
    END,
    true,
    NOW(),
    NOW()
  )
  RETURNING id INTO new_user_id;

  -- Retornar éxito
  RETURN jsonb_build_object(
    'success', true,
    'user_id', new_user_id,
    'email', p_email,
    'message', 'Perfil creado exitosamente. El usuario debe registrarse con este email para activar su cuenta.'
  );

EXCEPTION
  WHEN OTHERS THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', SQLERRM
    );
END;
$$;


--
-- Name: FUNCTION create_user_atomic_admin(p_email text, p_password text, p_name text, p_role text, p_company_id uuid, p_assigned_store_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.create_user_atomic_admin(p_email text, p_password text, p_name text, p_role text, p_company_id uuid, p_assigned_store_id uuid) IS 'Crea un usuario completo (auth.users + public.users) de forma atómica desde el panel admin. Maneja encriptación de contraseñas y vinculación automática.';


--
-- Name: create_user_directly(text, text, text, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_user_directly(p_email text, p_password text, p_name text, p_role text, p_company_id uuid, p_assigned_store_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'extensions'
    AS $$
DECLARE
  new_user_id UUID;
  new_auth_user_id UUID;
BEGIN
  IF EXISTS (SELECT 1 FROM auth.users WHERE email = p_email) THEN
    RETURN jsonb_build_object('success', false, 'error', 'El correo ya está registrado');
  END IF;

  new_auth_user_id := gen_random_uuid();

    instance_id, id, aud, role, email, encrypted_password, email_confirmed_at,
    created_at, updated_at, confirmation_token, raw_app_meta_data, raw_user_meta_data
  ) VALUES (
    '00000000-0000-0000-0000-000000000000', new_auth_user_id, 'authenticated', 'authenticated',
    p_email, extensions.crypt(p_password, extensions.gen_salt('bf')), NOW(),
    NOW(), NOW(), '', 
    jsonb_build_object('provider', 'email', 'providers', ARRAY['email']),
    jsonb_build_object('name', p_name)
  );

    auth_user_id, company_id, email, name, role, assigned_store_id, active, created_at, updated_at
  ) VALUES (
    new_auth_user_id, p_company_id, p_email, p_name, p_role, p_assigned_store_id, true, NOW(), NOW()
  )
  RETURNING id INTO new_user_id;

  RETURN jsonb_build_object('success', true, 'user_id', new_user_id, 'auth_user_id', new_auth_user_id, 'email', p_email);
EXCEPTION
  WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$$;


--
-- Name: delete_product(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_product(p_product_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_company_id UUID;
    v_user_id UUID;
    v_product_name TEXT;
    v_rows_affected INTEGER;
    v_sales_count INTEGER;
BEGIN
    -- 1. Obtener Company ID y User ID del usuario logueado (Seguridad)
    SELECT company_id, id INTO v_company_id, v_user_id
    FROM public.users
    WHERE auth_user_id = auth.uid()
    LIMIT 1;

    IF v_company_id IS NULL OR v_user_id IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Usuario no encontrado o no asociado a una compañía'
        );
    END IF;

    -- 2. Verificar que el usuario es admin
    IF NOT EXISTS (
        SELECT 1 FROM public.users
        WHERE id = v_user_id
        AND role = 'admin'
    ) THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Solo los administradores pueden eliminar productos'
        );
    END IF;

    -- 3. Verificar que el producto existe y pertenece a la empresa
    SELECT name INTO v_product_name
    FROM public.products
    WHERE id = p_product_id
    AND company_id = v_company_id;

    IF v_product_name IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Producto no encontrado o no pertenece a tu empresa'
        );
    END IF;

    -- 4. Verificar si el producto tiene ventas asociadas (para información)
    SELECT COUNT(*) INTO v_sales_count
    FROM public.sale_items
    WHERE product_id = p_product_id;

    -- 5. SOFT DELETE: Desactivar el producto en lugar de borrarlo
    -- Esto mantiene la integridad histórica de las ventas
    UPDATE public.products
    SET active = false,
        updated_at = NOW()
    WHERE id = p_product_id
    AND company_id = v_company_id
    RETURNING 1 INTO v_rows_affected;

    IF v_rows_affected = 0 THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'No se pudo desactivar el producto'
        );
    END IF;

    -- 6. Retornar resultado exitoso
    RETURN jsonb_build_object(
        'success', true,
        'message', 'Producto desactivado exitosamente',
        'product_id', p_product_id,
        'product_name', v_product_name,
        'sales_count', v_sales_count,
        'note', CASE 
            WHEN v_sales_count > 0 THEN 
                'El producto tiene ' || v_sales_count || ' venta(s) asociada(s). Se mantiene en el historial.'
            ELSE 
                'El producto no tiene ventas asociadas.'
        END
    );

EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object(
        'success', false,
        'error', 'Error al desactivar el producto: ' || SQLERRM
    );
END;
$$;


--
-- Name: FUNCTION delete_product(p_product_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.delete_product(p_product_id uuid) IS 'Desactiva un producto (Soft Delete) estableciendo active = false. 
NO elimina físicamente el producto para mantener la integridad histórica de las ventas.
El producto desaparecerá del POS pero seguirá existiendo en la base de datos para reportes históricos.
Solo administradores pueden ejecutar esta función.';


--
-- Name: delete_sale_and_restore_inventory(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_sale_and_restore_inventory(p_sale_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_sale_record RECORD;
    v_sale_item RECORD;
    v_company_id UUID;
    v_store_id UUID;
    v_user_company_id UUID;
    v_user_id UUID;
    v_deleted_items JSONB := '[]'::jsonb;
    v_item JSONB;
    v_movements_created INTEGER := 0;
    v_movements_deleted INTEGER := 0;
    v_rows_affected INTEGER;
    v_movement_exists BOOLEAN;
    v_warnings TEXT[] := ARRAY[]::TEXT[];
    v_restored_count INTEGER := 0;
    v_skipped_count INTEGER := 0;
BEGIN
    -- Get user's company and user ID
    SELECT company_id, id INTO v_user_company_id, v_user_id
    FROM public.users
    WHERE auth_user_id = auth.uid()
    LIMIT 1;

    IF v_user_company_id IS NULL OR v_user_id IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Usuario no encontrado o no asociado a una empresa'
        );
    END IF;

    -- Check if user is admin or manager
    IF NOT EXISTS (
        SELECT 1 FROM public.users 
        WHERE auth_user_id = auth.uid() 
        AND company_id = v_user_company_id 
        AND role IN ('admin', 'manager')
    ) THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Permisos insuficientes. Solo administradores y gerentes pueden eliminar ventas'
        );
    END IF;

    -- Get sale information
    SELECT * INTO v_sale_record
    FROM public.sales
    WHERE id = p_sale_id 
    AND company_id = v_user_company_id;

    IF NOT FOUND THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Venta no encontrada o no pertenece a tu empresa'
        );
    END IF;

    -- Check if sale is completed (only allow deletion of completed sales)
    IF v_sale_record.status != 'completed' THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Solo se pueden eliminar ventas completadas'
        );
    END IF;

    v_company_id := v_sale_record.company_id;
    v_store_id := v_sale_record.store_id;

    -- PASO 1: Eliminar registros de inventory_movements asociados a esta venta (OUT)
    DELETE FROM public.inventory_movements 
    WHERE sale_id = p_sale_id;
    
    GET DIAGNOSTICS v_movements_deleted = ROW_COUNT;

    -- PASO 2: Get all sale items, restore inventory with validation
    FOR v_sale_item IN 
        SELECT * FROM public.sale_items 
        WHERE sale_id = p_sale_id
    LOOP
        -- ========================================================================
        -- VALIDACIÓN CRÍTICA: Verificar que la venta realmente descontó stock
        -- ========================================================================
        -- Buscar evidencia de que se descontó stock (movimiento OUT o verificación de integridad)
        -- Si no hay evidencia, NO restaurar stock (previene stock fantasma)
        
        -- Opción 1: Verificar si existe movimiento OUT (si la tabla tiene sale_id)
        BEGIN
            SELECT EXISTS (
                SELECT 1 FROM public.inventory_movements
                WHERE sale_id = p_sale_id
                  AND product_id = v_sale_item.product_id
                  AND type = 'OUT'
                  AND qty = -v_sale_item.qty
            ) INTO v_movement_exists;
        EXCEPTION
            WHEN OTHERS THEN
                -- Si la tabla no tiene sale_id o hay otro error, continuar con validación alternativa
                v_movement_exists := NULL;
        END;

        -- ========================================================================
        -- RESTAURAR STOCK CON VALIDACIÓN POST-UPDATE
        -- ========================================================================
        -- Si no hay evidencia de movimiento, aún así intentar restaurar,
        -- pero validar que el UPDATE funcionó para detectar anomalías
        
        UPDATE public.inventories 
        SET qty = qty + v_sale_item.qty,
            updated_at = NOW()
        WHERE product_id = v_sale_item.product_id 
        AND store_id = v_store_id
        AND company_id = v_company_id;

        -- ✅ VALIDACIÓN CRÍTICA: Verificar que el UPDATE afectó una fila
        GET DIAGNOSTICS v_rows_affected = ROW_COUNT;

        IF v_rows_affected = 0 THEN
            -- El inventario no existe, crearlo con el stock a restaurar
            -- PERO: Esto podría crear stock fantasma si la venta nunca descontó
            VALUES (v_company_id, v_store_id, v_sale_item.product_id, v_sale_item.qty, 0)
            ON CONFLICT (company_id, store_id, product_id) DO UPDATE
            SET qty = inventories.qty + v_sale_item.qty,
                updated_at = NOW();
            
            -- ⚠️ WARNING: Registrar advertencia
            v_warnings := array_append(v_warnings, 
                format('Producto %s (ID: %s): Inventario no existía, creado con stock restaurado. Verificar si la venta realmente descontó stock.',
                    v_sale_item.product_name, v_sale_item.product_id));
            v_restored_count := v_restored_count + 1;
        ELSE
            -- ✅ UPDATE exitoso
            v_restored_count := v_restored_count + 1;
            
            -- Si no hay evidencia de movimiento OUT, registrar advertencia
            IF v_movement_exists = FALSE THEN
                v_warnings := array_append(v_warnings,
                    format('Producto %s (ID: %s): Stock restaurado pero no se encontró movimiento OUT asociado. Verificar integridad.',
                        v_sale_item.product_name, v_sale_item.product_id));
            END IF;
        END IF;

        -- 2.2. Register inventory movement for restoration (AUDIT TRAIL)
        BEGIN
                product_id,
                store_from_id,
                qty,
                type,
                reason,
                user_id,
                company_id,
                created_at
            )
            VALUES (
                v_sale_item.product_id,
                v_store_id,
                v_sale_item.qty,
                'IN',
                'Restitución por cancelación de venta - Factura: ' || COALESCE(v_sale_record.invoice_number, v_sale_record.id::text) || 
                ' - Cliente: ' || COALESCE(v_sale_record.customer_id::text, 'Cliente General'),
                v_user_id,
                v_company_id,
                NOW()
            );
            v_movements_created := v_movements_created + 1;
        EXCEPTION
            WHEN OTHERS THEN
                -- Si falla la inserción de movimiento (ej: columna sale_id no existe), continuar
                -- La restitución de stock ya se hizo, esto es solo para auditoría
                NULL;
        END;

        -- 2.3. Add item to deleted items list
        v_item := jsonb_build_object(
            'product_id', v_sale_item.product_id,
            'product_name', v_sale_item.product_name,
            'qty_restored', v_sale_item.qty,
            'price_usd', v_sale_item.price_usd
        );
        v_deleted_items := v_deleted_items || v_item;
    END LOOP;

    -- PASO 3: Delete sale items first (due to foreign key constraint)
    DELETE FROM public.sale_items 
    WHERE sale_id = p_sale_id;

    -- PASO 4: Delete the sale
    DELETE FROM public.sales 
    WHERE id = p_sale_id;

    -- Return success response with audit information and warnings
    RETURN jsonb_build_object(
        'success', true,
        'message', 'Venta eliminada exitosamente e inventario restaurado',
        'sale_id', p_sale_id,
        'invoice_number', v_sale_record.invoice_number,
        'total_usd', v_sale_record.total_usd,
        'total_bs', v_sale_record.total_bs,
        'deleted_items', v_deleted_items,
        'items_count', jsonb_array_length(v_deleted_items),
        'restored_count', v_restored_count,
        'skipped_count', v_skipped_count,
        'movements_created', v_movements_created,
        'movements_deleted', v_movements_deleted,
        'warnings', CASE 
            WHEN array_length(v_warnings, 1) > 0 THEN to_jsonb(v_warnings)
            ELSE '[]'::jsonb
        END
    );

EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object(
        'success', false,
        'error', 'Error al eliminar la venta: ' || SQLERRM
    );
END;
$$;


--
-- Name: FUNCTION delete_sale_and_restore_inventory(p_sale_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.delete_sale_and_restore_inventory(p_sale_id uuid) IS 'Elimina una venta y restaura el inventario con validación post-update para prevenir stock fantasma. 
Valida que el UPDATE de stock funcionó y registra advertencias si no hay evidencia de que la venta descontó stock originalmente.';


--
-- Name: delete_sale_with_refund(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_sale_with_refund(p_sale_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    item RECORD;
    v_store_id UUID;
    v_company_id UUID;
BEGIN
    -- 1. Obtener IDs de la venta
    SELECT store_id, company_id INTO v_store_id, v_company_id
    FROM sales
    WHERE id = p_sale_id;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'message', 'Venta no encontrada.');
    END IF;

    -- 2. Devolución de Stock (El punto crítico de la lógica)
    FOR item IN
        SELECT product_id, qty
        FROM sale_items
        WHERE sale_id = p_sale_id
    LOOP
        -- Sumar la cantidad de vuelta al inventario (Blindaje)
        UPDATE inventories
        SET qty = qty + item.qty, updated_at = NOW()
        WHERE company_id = v_company_id
          AND store_id = v_store_id
          AND product_id = item.product_id;
        
        IF NOT FOUND THEN
            RAISE NOTICE 'Advertencia: Inventario no encontrado para %', item.product_id;
        END IF;
    END LOOP;

    -- 3. Eliminar todos los registros de la venta (Orden de eliminación)
    DELETE FROM sale_payments WHERE sale_id = p_sale_id;
    DELETE FROM krece_financing WHERE sale_id = p_sale_id;
    DELETE FROM sale_items WHERE sale_id = p_sale_id;
    
    -- Finalmente, eliminar la cabecera de la venta
    DELETE FROM sales WHERE id = p_sale_id;

    RETURN jsonb_build_object('success', true, 'message', 'Venta eliminada con devolución de stock completada.');
EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'message', SQLERRM);
END;
$$;


--
-- Name: delete_user_atomic_admin(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_user_atomic_admin(p_user_profile_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
DECLARE
  v_auth_user_id UUID;
  v_user_email TEXT;
  v_user_name TEXT;
  v_company_id UUID;
  v_admin_id UUID;
BEGIN
  -- Obtener información del usuario a eliminar
  SELECT auth_user_id, email, name, company_id
  INTO v_auth_user_id, v_user_email, v_user_name, v_company_id
  FROM users
  WHERE id = p_user_profile_id;

  -- Verificar que el usuario existe
  IF v_auth_user_id IS NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Usuario no encontrado'
    );
  END IF;

  -- Obtener el ID del primer admin activo de la empresa (para reasignar dependencias)
  SELECT id INTO v_admin_id
  FROM users
  WHERE company_id = v_company_id
    AND role = 'admin'
    AND active = true
  ORDER BY created_at ASC
  LIMIT 1;

  -- Si no hay admin, usar el mismo usuario (mejor que dejar NULL)
  IF v_admin_id IS NULL THEN
    v_admin_id := p_user_profile_id;
  END IF;

  -- Actualizar dependencias en inventory_transfers
  UPDATE inventory_transfers
  SET transferred_by = v_admin_id
  WHERE transferred_by = p_user_profile_id;

  -- Actualizar dependencias en sales (cashier_id)
  UPDATE sales
  SET cashier_id = v_admin_id
  WHERE cashier_id = p_user_profile_id;

  -- Actualizar dependencias en admin_activity_log
  UPDATE admin_activity_log
  SET user_id = v_admin_id
  WHERE user_id = p_user_profile_id;

  -- Eliminar el perfil de public.users primero (para evitar problemas de FK)
  DELETE FROM users
  WHERE id = p_user_profile_id;

  -- Eliminar el usuario de auth.users
  IF v_auth_user_id IS NOT NULL THEN
    DELETE FROM auth.users
    WHERE id = v_auth_user_id;
  END IF;

  -- Retornar éxito
  RETURN jsonb_build_object(
    'success', true,
    'message', format('Usuario %s eliminado exitosamente', COALESCE(v_user_name, v_user_email))
  );

EXCEPTION
  WHEN OTHERS THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', SQLERRM
    );
END;
$$;


--
-- Name: FUNCTION delete_user_atomic_admin(p_user_profile_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.delete_user_atomic_admin(p_user_profile_id uuid) IS 'Elimina un usuario de forma permanente (public.users + auth.users) y reasigna sus dependencias al admin principal de la empresa.';


--
-- Name: generate_invoice_number(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_invoice_number(p_company_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_next_id BIGINT;
  v_date_part TEXT;
  v_invoice_number TEXT;
BEGIN
  -- Obtener el siguiente ID de forma atómica (GLOBAL, CONTINUA, +1)
  v_next_id := nextval('global_invoice_seq');
  
  -- Formatear la parte de fecha (YYYYMMDD)
  v_date_part := to_char(CURRENT_DATE, 'YYYYMMDD');
  
  -- ✅ Formato: FAC-YYYYMMDD-NNNNN (5 dígitos)
  -- Ejemplo: FAC-20251205-01001 (en lugar de FAC-20251205-001001)
  v_invoice_number := 'FAC-' || v_date_part || '-' || LPAD(v_next_id::TEXT, 5, '0');
  
  RETURN v_invoice_number;
END;
$$;


--
-- Name: FUNCTION generate_invoice_number(p_company_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.generate_invoice_number(p_company_id uuid) IS 'Genera un número de factura único y atómico usando una secuencia GLOBAL de PostgreSQL. La secuencia es CONTINUA (no se reinicia por día ni sucursal) e incrementa +1 con cada venta. Garantiza monotonicidad y elimina race conditions. Formato: FAC-YYYYMMDD-NNNNN (5 dígitos)';


