--
-- Name: get_company_inventory_summary(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_company_inventory_summary() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_company_id UUID;
    v_summary JSONB;
BEGIN
    -- Obtener company_id del usuario
    SELECT company_id INTO v_company_id
    FROM public.users
    WHERE auth_user_id = auth.uid()
    LIMIT 1;

    IF v_company_id IS NULL THEN
        RAISE EXCEPTION 'Usuario no está vinculado a una compañía.';
    END IF;

    -- Calcular resumen SOLO para productos activos
    SELECT jsonb_build_object(
        'company_id', v_company_id,
        'total_products', COUNT(DISTINCT i.product_id) FILTER (WHERE p.active = true),
        'total_stock', COALESCE(SUM(i.qty) FILTER (WHERE p.active = true), 0),
        'total_value', COALESCE(SUM(i.qty * COALESCE(p.sale_price_usd, 0)) FILTER (WHERE p.active = true), 0),
        'total_stores', COUNT(DISTINCT i.store_id) FILTER (WHERE p.active = true),
        'low_stock_count', COUNT(DISTINCT i.product_id) FILTER (
            WHERE p.active = true 
            AND i.qty <= i.min_qty 
            AND i.qty > 0
        ),
        'out_of_stock_count', COUNT(DISTINCT i.product_id) FILTER (
            WHERE p.active = true 
            AND i.qty = 0
        )
    ) INTO v_summary
    FROM public.inventories i
    INNER JOIN public.products p ON i.product_id = p.id
    WHERE i.company_id = v_company_id
    AND p.active = true;  -- ⚠️ FILTRO CRÍTICO: Solo productos activos

    RETURN v_summary;
END;
$$;


--
-- Name: FUNCTION get_company_inventory_summary(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_company_inventory_summary() IS 'Devuelve un resumen de inventario para toda la compañía del usuario. 
IMPORTANTE: Solo incluye productos activos (active = true).';


--
-- Name: get_dashboard_store_performance(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_dashboard_store_performance(p_company_id uuid DEFAULT NULL::uuid, p_start_date timestamp with time zone DEFAULT (CURRENT_DATE - '30 days'::interval), p_end_date timestamp with time zone DEFAULT CURRENT_TIMESTAMP) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_company_id UUID;
  v_summary JSONB;
BEGIN
  -- Obtener company_id del usuario si no se proporciona
  IF p_company_id IS NULL THEN
    v_company_id := public.get_user_company_id();
  ELSE
    v_company_id := p_company_id;
  END IF;

  -- Validar que company_id no sea NULL
  IF v_company_id IS NULL THEN
    RETURN jsonb_build_object(
      'error', true,
      'message', 'Company ID is required'
    );
  END IF;

  -- Construir resumen usando CTEs para evitar duplicación de filas
  WITH sales_filtered AS (
    -- CTE 1: Ventas filtradas por fecha, status y company_id
    SELECT 
      id,
      store_id,
      total_usd,
      created_at
    FROM public.sales
    WHERE company_id = v_company_id
      AND created_at >= p_start_date
      AND created_at < p_end_date
      AND status = 'completed'
  ),
  sale_items_agg AS (
    -- CTE 2: Agregar sale_items por sale_id (evita duplicación)
    SELECT 
      si.sale_id,
      COALESCE(SUM(si.subtotal_usd), 0) AS total_subtotal,
      COALESCE(SUM(si.qty * p.cost_usd), 0) AS total_cost,
      COALESCE(SUM(si.qty), 0) AS total_quantity
    FROM public.sale_items si
    INNER JOIN sales_filtered sf ON si.sale_id = sf.id
    LEFT JOIN public.products p ON si.product_id = p.id
    GROUP BY si.sale_id
  ),
  sale_payments_agg AS (
    -- CTE 3: Agregar sale_payments por sale_id (evita duplicación)
    SELECT 
      sp.sale_id,
      COALESCE(SUM(sp.amount_usd), 0) AS total_payments
    FROM public.sale_payments sp
    INNER JOIN sales_filtered sf ON sp.sale_id = sf.id
    GROUP BY sp.sale_id
  ),
  store_performance AS (
    -- CTE 4: Combinar todo por store_id
    SELECT 
      sf.store_id,
      COUNT(DISTINCT sf.id) AS orders_count,
      COALESCE(SUM(sf.total_usd), 0) AS total_invoiced,
      COALESCE(SUM(spa.total_payments), 0) AS net_income_real,
      COALESCE(SUM(sia.total_subtotal), 0) AS total_subtotal,
      COALESCE(SUM(sia.total_cost), 0) AS total_cost,
      CASE
        WHEN COUNT(DISTINCT sf.id) > 0
        THEN COALESCE(SUM(sf.total_usd), 0) / COUNT(DISTINCT sf.id)
        ELSE 0
      END AS avg_order_value
    FROM sales_filtered sf
    LEFT JOIN sale_items_agg sia ON sf.id = sia.sale_id
    LEFT JOIN sale_payments_agg spa ON sf.id = spa.sale_id
    GROUP BY sf.store_id
  )
  -- SELECT FINAL: Construir JSON estructurado sin anidaciones
  SELECT jsonb_agg(
    jsonb_build_object(
      'store_id', s.id,
      'store_name', s.name,
      'total_invoiced', COALESCE(sp.total_invoiced, 0),
      'net_income_real', COALESCE(sp.net_income_real, 0),
      -- ✅ FIX: Usar total_invoiced en lugar de total_subtotal para profit
      'estimated_profit', COALESCE(
        sp.total_invoiced - sp.total_cost,
        0
      ),
      'orders_count', COALESCE(sp.orders_count, 0),
      'avg_order_value', COALESCE(sp.avg_order_value, 0),
      -- ✅ FIX: Usar total_invoiced en lugar de total_subtotal para profit_margin
      'profit_margin_percent', CASE
        WHEN COALESCE(sp.total_invoiced, 0) > 0
        THEN ((COALESCE(sp.total_invoiced, 0) - COALESCE(sp.total_cost, 0)) / COALESCE(sp.total_invoiced, 0)) * 100
        ELSE 0
      END
    )
    ORDER BY COALESCE(sp.total_invoiced, 0) DESC
  )
  INTO v_summary
  FROM public.stores s
  LEFT JOIN store_performance sp ON s.id = sp.store_id
  WHERE s.company_id = v_company_id
    AND s.active = true;

  RETURN jsonb_build_object(
    'summary', COALESCE(v_summary, '[]'::jsonb),
    'period', jsonb_build_object(
      'start_date', p_start_date,
      'end_date', p_end_date
    ),
    'generated_at', NOW()
  );
EXCEPTION
  WHEN OTHERS THEN
    RETURN jsonb_build_object(
      'error', true,
      'message', SQLERRM,
      'code', SQLSTATE
    );
END;
$$;


--
-- Name: get_executive_summary_v2(uuid, uuid, timestamp with time zone, timestamp with time zone, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_executive_summary_v2(p_company_id uuid DEFAULT NULL::uuid, p_store_id uuid DEFAULT NULL::uuid, p_date_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_date_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_category character varying DEFAULT NULL::character varying) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_company_id UUID;
  v_result JSONB;
BEGIN
  -- 1. Seguridad: Obtener company_id del usuario autenticado
  SELECT company_id INTO v_user_company_id
  FROM public.users
  WHERE auth_user_id = auth.uid()
  LIMIT 1;

  IF v_user_company_id IS NULL THEN
    RETURN jsonb_build_object(
      'error', true,
      'message', 'Usuario no autenticado o sin company_id'
    );
  END IF;

  -- 2. Query Principal (SOLO SELECT - Sin bloqueos)
  WITH sales_filtered AS (
    -- CTE 1: Ventas filtradas por fecha, status y company_id
    SELECT 
      s.id,
      s.store_id,
      s.total_usd,
      s.subtotal_usd,
      s.tax_amount_usd,
      s.total_bs,
      s.bcv_rate_used,
      s.created_at,
      s.krece_enabled,
      s.krece_initial_amount_usd,
      s.krece_financed_amount_usd,
      s.cashea_enabled,
      s.cashea_initial_amount_usd,
      s.cashea_financed_amount_usd,
      s.is_mixed_payment,
      s.payment_method
    FROM public.sales s
    WHERE s.company_id = COALESCE(p_company_id, v_user_company_id)
      AND (p_store_id IS NULL OR s.store_id = p_store_id)
      AND (p_date_from IS NULL OR s.created_at >= p_date_from)
      AND (p_date_to IS NULL OR s.created_at <= p_date_to)
      AND s.status = 'completed'
  ),
  sale_payments_agg AS (
    -- CTE 2: Agregar sale_payments con lógica blindada de Ingreso Real
    SELECT 
      sp.sale_id,
      -- ✅ LÓGICA BLINDADA: Ingreso Real = amount_usd + (amount_bs convertido a USD)
      COALESCE(SUM(
        sp.amount_usd + (
          COALESCE(sp.amount_bs, 0) / NULLIF(s.bcv_rate_used, 0)
        )
      ), 0) AS net_income_real,
      COALESCE(SUM(sp.amount_usd), 0) AS total_payments_usd,
      COALESCE(SUM(sp.amount_bs), 0) AS total_payments_bs
    FROM public.sale_payments sp
    INNER JOIN sales_filtered sf ON sp.sale_id = sf.id
    INNER JOIN public.sales s ON sp.sale_id = s.id
    GROUP BY sp.sale_id
  ),
  sale_items_agg AS (
    -- CTE 3: Agregar sale_items para cálculo de rentabilidad
    SELECT 
      si.sale_id,
      COALESCE(SUM(si.subtotal_usd), 0) AS total_subtotal,
      COALESCE(SUM(si.qty * p.cost_usd), 0) AS total_cost,
      COALESCE(SUM(si.qty), 0) AS total_quantity
    FROM public.sale_items si
    INNER JOIN sales_filtered sf ON si.sale_id = sf.id
    LEFT JOIN public.products p ON si.product_id = p.id
    WHERE (p_category IS NULL OR p.category = p_category)
    GROUP BY si.sale_id
  ),
  store_performance AS (
    -- CTE 4: Combinar todo por store_id
    SELECT 
      sf.store_id,
      COUNT(DISTINCT sf.id) AS orders_count,
      COALESCE(SUM(sf.total_usd), 0) AS total_invoiced,
      COALESCE(SUM(spa.net_income_real), 0) AS net_income_real,
      COALESCE(SUM(sia.total_subtotal), 0) AS total_subtotal,
      COALESCE(SUM(sia.total_cost), 0) AS total_cost,
      COALESCE(SUM(sia.total_quantity), 0) AS total_quantity,
      CASE
        WHEN COUNT(DISTINCT sf.id) > 0
        THEN COALESCE(SUM(sf.total_usd), 0) / COUNT(DISTINCT sf.id)
        ELSE 0
      END AS avg_order_value
    FROM sales_filtered sf
    LEFT JOIN sale_items_agg sia ON sf.id = sia.sale_id
    LEFT JOIN sale_payments_agg spa ON sf.id = spa.sale_id
    GROUP BY sf.store_id
  ),
  payment_methods_agg AS (
    -- CTE 5: Agregar métodos de pago
    SELECT 
      sp.payment_method,
      COALESCE(SUM(sp.amount_usd), 0) AS total_usd,
      COALESCE(SUM(sp.amount_bs), 0) AS total_bs,
      COUNT(*) AS count
    FROM public.sale_payments sp
    INNER JOIN sales_filtered sf ON sp.sale_id = sf.id
    GROUP BY sp.payment_method
  ),
  krece_summary AS (
    -- CTE 6: Resumen de Krece
    SELECT 
      COUNT(*) FILTER (WHERE sf.krece_enabled = true) AS krece_orders,
      COALESCE(SUM(sf.krece_initial_amount_usd) FILTER (WHERE sf.krece_enabled = true), 0) AS krece_initial_total,
      COALESCE(SUM(sf.krece_financed_amount_usd) FILTER (WHERE sf.krece_enabled = true), 0) AS krece_financed_total
    FROM sales_filtered sf
  ),
  cashea_summary AS (
    -- CTE 7: Resumen de Cashea
    SELECT 
      COUNT(*) FILTER (WHERE sf.cashea_enabled = true) AS cashea_orders,
      COALESCE(SUM(sf.cashea_initial_amount_usd) FILTER (WHERE sf.cashea_enabled = true), 0) AS cashea_initial_total,
      COALESCE(SUM(sf.cashea_financed_amount_usd) FILTER (WHERE sf.cashea_enabled = true), 0) AS cashea_financed_total
    FROM sales_filtered sf
  )
  -- SELECT FINAL: Construir JSON estructurado
  SELECT jsonb_build_object(
    'summary', jsonb_build_object(
      'total_invoiced', COALESCE(SUM(sp.total_invoiced), 0),
      'net_income_real', COALESCE(SUM(sp.net_income_real), 0),
      'total_orders', COALESCE(SUM(sp.orders_count), 0),
      'avg_order_value', CASE
        WHEN COALESCE(SUM(sp.orders_count), 0) > 0
        THEN COALESCE(SUM(sp.total_invoiced), 0) / SUM(sp.orders_count)
        ELSE 0
      END,
      'total_subtotal', COALESCE(SUM(sp.total_subtotal), 0),
      'total_cost', COALESCE(SUM(sp.total_cost), 0),
      'estimated_profit', COALESCE(SUM(sp.total_subtotal) - SUM(sp.total_cost), 0),
      'profit_margin_percent', CASE
        WHEN COALESCE(SUM(sp.total_subtotal), 0) > 0
        THEN ((COALESCE(SUM(sp.total_subtotal), 0) - COALESCE(SUM(sp.total_cost), 0)) / COALESCE(SUM(sp.total_subtotal), 0)) * 100
        ELSE 0
      END,
      'total_quantity', COALESCE(SUM(sp.total_quantity), 0)
    ),
    'stores', COALESCE((
      SELECT jsonb_agg(
        jsonb_build_object(
          'store_id', s.id,
          'store_name', s.name,
          'total_invoiced', COALESCE(sp.total_invoiced, 0),
          'net_income_real', COALESCE(sp.net_income_real, 0),
          'orders_count', COALESCE(sp.orders_count, 0),
          'avg_order_value', COALESCE(sp.avg_order_value, 0),
          'estimated_profit', COALESCE(sp.total_subtotal - sp.total_cost, 0),
          'profit_margin_percent', CASE
            WHEN COALESCE(sp.total_subtotal, 0) > 0
            THEN ((COALESCE(sp.total_subtotal, 0) - COALESCE(sp.total_cost, 0)) / COALESCE(sp.total_subtotal, 0)) * 100
            ELSE 0
          END,
          'total_quantity', COALESCE(sp.total_quantity, 0)
        )
        ORDER BY COALESCE(sp.total_invoiced, 0) DESC
      )
      FROM public.stores s
      LEFT JOIN store_performance sp ON s.id = sp.store_id
      WHERE s.company_id = COALESCE(p_company_id, v_user_company_id)
        AND s.active = true
    ), '[]'::jsonb),
    'payment_methods', COALESCE((
      SELECT jsonb_agg(
        jsonb_build_object(
          'method', pma.payment_method,
          'total_usd', pma.total_usd,
          'total_bs', pma.total_bs,
          'count', pma.count,
          'percentage', CASE
            WHEN (SELECT SUM(total_usd) FROM payment_methods_agg) > 0
            THEN (pma.total_usd / (SELECT SUM(total_usd) FROM payment_methods_agg)) * 100
            ELSE 0
          END
        )
        ORDER BY pma.total_usd DESC
      )
      FROM payment_methods_agg pma
    ), '[]'::jsonb),
    'krece', (
      SELECT jsonb_build_object(
        'orders', COALESCE(ks.krece_orders, 0),
        'initial_total', COALESCE(ks.krece_initial_total, 0),
        'financed_total', COALESCE(ks.krece_financed_total, 0)
      )
      FROM krece_summary ks
    ),
    'cashea', (
      SELECT jsonb_build_object(
        'orders', COALESCE(cs.cashea_orders, 0),
        'initial_total', COALESCE(cs.cashea_initial_total, 0),
        'financed_total', COALESCE(cs.cashea_financed_total, 0)
      )
      FROM cashea_summary cs
    ),
    'period', jsonb_build_object(
      'start_date', p_date_from,
      'end_date', p_date_to
    ),
    'generated_at', NOW()
  )
  INTO v_result
  FROM store_performance sp;

  RETURN COALESCE(v_result, jsonb_build_object('error', true, 'message', 'No se pudieron obtener los datos'));

EXCEPTION
  WHEN OTHERS THEN
    RETURN jsonb_build_object(
      'error', true,
      'message', SQLERRM,
      'code', SQLSTATE
    );
END;
$$;


--
-- Name: FUNCTION get_executive_summary_v2(p_company_id uuid, p_store_id uuid, p_date_from timestamp with time zone, p_date_to timestamp with time zone, p_category character varying); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_executive_summary_v2(p_company_id uuid, p_store_id uuid, p_date_from timestamp with time zone, p_date_to timestamp with time zone, p_category character varying) IS 'RPC de SOLO LECTURA para reportes ejecutivos blindados:
- Calcula Ingreso Real usando lógica blindada: amount_usd + (amount_bs / bcv_rate_used)
- Retorna métricas agregadas por tienda, método de pago, Krece y Cashea
- Respeta RLS automáticamente
- Solo SELECT - Sin UPDATE, INSERT, DELETE
- Sin bloqueos - No usa FOR UPDATE, FOR SHARE, LOCK TABLE
- No afecta funciones de escritura (process_sale, etc.)';


--
-- Name: get_inventory_financial_summary(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_inventory_financial_summary(p_company_id uuid DEFAULT NULL::uuid, p_store_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_company_id UUID;
  v_result JSONB;
BEGIN
  -- Obtener company_id del usuario si no se proporciona
  IF p_company_id IS NULL THEN
    v_company_id := public.get_user_company_id();
  ELSE
    v_company_id := p_company_id;
  END IF;

  -- Validar que company_id no sea NULL
  IF v_company_id IS NULL THEN
    RETURN jsonb_build_object(
      'error', true,
      'message', 'Company ID is required'
    );
  END IF;

  -- Usar CTEs para evitar agregaciones anidadas
  WITH inventory_aggregated AS (
    -- ✅ CTE PREVIO: Agregar inventario por producto (evita duplicados)
    -- 🔥 FILTRO DE SUCURSAL: Aplicar aquí para evitar duplicados cuando hay múltiples tiendas
    SELECT 
      inv.product_id,
      SUM(inv.qty) AS total_qty
    FROM public.inventories inv
    WHERE inv.company_id = v_company_id
      -- 🔥 FILTRO DE SUCURSAL: Solo cuando p_store_id está presente
      AND (p_store_id IS NULL OR inv.store_id = p_store_id)
    GROUP BY inv.product_id
  ),
  joined_data AS (
    -- ✅ CTE CORREGIDO: LEFT JOIN con products como base (incluye productos sin inventario)
    -- ✅ Usa inventario ya agregado para evitar duplicados
    SELECT 
      COALESCE(p.category, 'Sin Categoría') AS category,
      COALESCE(ia.total_qty, 0) AS qty,  -- ✅ Usar qty agregado (sin duplicados)
      p.cost_usd,
      p.sale_price_usd,
      p.id AS product_id,
      COALESCE(ia.total_qty, 0) * p.cost_usd AS cost_value,
      COALESCE(ia.total_qty, 0) * p.sale_price_usd AS retail_value,
      COALESCE(ia.total_qty, 0) * (p.sale_price_usd - p.cost_usd) AS profit_value
    FROM public.products p
    LEFT JOIN inventory_aggregated ia ON ia.product_id = p.id
    WHERE p.company_id = v_company_id
      AND p.active = true
  ),
  product_totals AS (
    -- ✅ CTE: Agregación global por producto (ya está agregado, pero mantenemos para compatibilidad)
    SELECT 
      product_id,
      COALESCE(SUM(qty), 0) AS total_qty_across_all_stores
    FROM joined_data
    GROUP BY product_id
  ),
  category_stats AS (
    -- CTE 2: Agregación por categoría (GROUP BY category)
    SELECT 
      category AS category_name,
      COALESCE(SUM(cost_value), 0) AS sum_cost,
      COALESCE(SUM(retail_value), 0) AS sum_retail,
      COALESCE(SUM(profit_value), 0) AS profit_potential,
      COUNT(DISTINCT product_id) AS product_count,
      COALESCE(SUM(qty), 0) AS count_items
    FROM joined_data
    GROUP BY category
  ),
  global_stats AS (
    -- CTE 3: Totales globales y alertas
    SELECT 
      COALESCE(SUM(cost_value), 0) AS total_cost,
      COALESCE(SUM(retail_value), 0) AS total_retail,
      COALESCE(SUM(retail_value), 0) - COALESCE(SUM(cost_value), 0) AS profit_potential,
      COALESCE(SUM(qty), 0) AS total_items,
      COUNT(DISTINCT jd.product_id) AS unique_products,
      -- ✅ Out of Stock - Basado en suma global (tiendas filtradas)
      COUNT(DISTINCT CASE 
        WHEN pt.total_qty_across_all_stores = 0 
        THEN pt.product_id 
      END) AS out_of_stock_count,
      -- ✅ Low Stock - Basado en suma global (tiendas filtradas)
      COUNT(DISTINCT CASE 
        WHEN pt.total_qty_across_all_stores > 0 
          AND pt.total_qty_across_all_stores <= 5 
        THEN pt.product_id 
      END) AS critical_stock_count
    FROM joined_data jd
    LEFT JOIN product_totals pt ON jd.product_id = pt.product_id
  )
  -- SELECT FINAL: Construir JSONB combinando global_stats y subquery a category_stats
  SELECT jsonb_build_object(
    'total_cost_value', gs.total_cost,
    'total_retail_value', gs.total_retail,
    'profit_potential', gs.profit_potential,
    'total_items', gs.total_items,
    'out_of_stock_count', COALESCE(gs.out_of_stock_count, 0),
    'critical_stock_count', COALESCE(gs.critical_stock_count, 0),
    'category_breakdown', (
      SELECT COALESCE(jsonb_agg(
        jsonb_build_object(
          'category_name', cs.category_name,
          'total_cost_value', cs.sum_cost,
          'total_retail_value', cs.sum_retail,
          'profit_potential', cs.profit_potential,
          'items_count', cs.product_count,
          'total_quantity', cs.count_items,
          'percentage_of_total', CASE
            WHEN gs.total_retail > 0
            THEN (cs.sum_retail / gs.total_retail) * 100
            ELSE 0
          END
        )
        ORDER BY cs.sum_retail DESC
      ), '[]'::jsonb)
      FROM category_stats cs
      CROSS JOIN global_stats gs
    ),
    'calculated_at', NOW()
  )
  INTO v_result
  FROM global_stats gs;

  RETURN COALESCE(v_result, jsonb_build_object('error', true, 'message', 'No data found'));
EXCEPTION
  WHEN OTHERS THEN
    RETURN jsonb_build_object(
      'error', true,
      'message', SQLERRM,
      'code', SQLSTATE
    );
END;
$$;


--
-- Name: FUNCTION get_inventory_financial_summary(p_company_id uuid, p_store_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_inventory_financial_summary(p_company_id uuid, p_store_id uuid) IS 'Función corregida para incluir todos los productos activos, incluso aquellos sin inventario.
Usa LEFT JOIN con agregación previa para evitar duplicados cuando hay múltiples tiendas.
Garantiza totalización correcta de valores financieros.';


--
-- Name: get_krece_accounts_summary(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_krece_accounts_summary(p_company_id uuid) RETURNS TABLE(total_pending_usd numeric, total_pending_bs numeric, total_paid_usd numeric, total_paid_bs numeric, total_overdue_usd numeric, total_overdue_bs numeric, count_pending integer, count_paid integer, count_overdue integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- 🛡️ SEGURIDAD: Verificar que el usuario tenga acceso a esta compañía
  -- RLS en la tabla krece_accounts_receivable ya filtra por company_id
  
  RETURN QUERY
  SELECT 
    -- Totales pendientes
    COALESCE(SUM(CASE WHEN status = 'pending' THEN amount_usd ELSE 0 END), 0) AS total_pending_usd,
    COALESCE(SUM(CASE WHEN status = 'pending' THEN amount_bs ELSE 0 END), 0) AS total_pending_bs,
    
    -- Totales pagados
    COALESCE(SUM(CASE WHEN status = 'paid' THEN amount_usd ELSE 0 END), 0) AS total_paid_usd,
    COALESCE(SUM(CASE WHEN status = 'paid' THEN amount_bs ELSE 0 END), 0) AS total_paid_bs,
    
    -- Totales vencidos
    COALESCE(SUM(CASE WHEN status = 'overdue' THEN amount_usd ELSE 0 END), 0) AS total_overdue_usd,
    COALESCE(SUM(CASE WHEN status = 'overdue' THEN amount_bs ELSE 0 END), 0) AS total_overdue_bs,
    
    -- Contadores
    COUNT(CASE WHEN status = 'pending' THEN 1 END)::INTEGER AS count_pending,
    COUNT(CASE WHEN status = 'paid' THEN 1 END)::INTEGER AS count_paid,
    COUNT(CASE WHEN status = 'overdue' THEN 1 END)::INTEGER AS count_overdue
  FROM public.krece_accounts_receivable
  WHERE company_id = p_company_id;
END;
$$;


--
-- Name: FUNCTION get_krece_accounts_summary(p_company_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_krece_accounts_summary(p_company_id uuid) IS 'Devuelve un resumen de cuentas por cobrar de Krece agrupado por estado (pending, paid, overdue). Respeta RLS automáticamente.';


--
-- Name: get_public_bcv_rate(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_public_bcv_rate() RETURNS numeric
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    AS $$
DECLARE
  v_rate NUMERIC(12,4);
BEGIN
  -- 1. Intentar manual_bcv_rate desde system_settings (primera empresa con valor)
  SELECT manual_bcv_rate INTO v_rate
  FROM public.system_settings
  WHERE manual_bcv_rate IS NOT NULL AND manual_bcv_rate > 0
  ORDER BY company_id
  LIMIT 1;

  -- 2. Fallback a bcv_rates
  IF v_rate IS NULL THEN
    SELECT rate INTO v_rate
    FROM public.bcv_rates
    ORDER BY fetched_at DESC
    LIMIT 1;
  END IF;

  -- 3. Fallback final (evitar NULL)
  RETURN COALESCE(v_rate, 41.73);
END;
$$;


--
-- Name: FUNCTION get_public_bcv_rate(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_public_bcv_rate() IS 'Retorna tasa BCV para web pública: manual_bcv_rate de system_settings o última de bcv_rates.';


--
-- Name: get_public_web_product_stock_by_store(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_public_web_product_stock_by_store(p_product_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    AS $$
DECLARE
  v_stock_by_store JSONB;
  v_product_company_id UUID;
BEGIN
  -- Obtener company_id del producto
  SELECT company_id INTO v_product_company_id
  FROM public.products
  WHERE id = p_product_id
  LIMIT 1;

  IF v_product_company_id IS NULL THEN
    RETURN jsonb_build_array();
  END IF;

  -- Construir array JSON con stock por sucursal
  SELECT jsonb_agg(
    jsonb_build_object(
      'store_id', s.id,
      'store_name', s.name,
      'qty', COALESCE(i.qty, 0)
    )
    ORDER BY s.name
  ) INTO v_stock_by_store
  FROM public.stores s
  LEFT JOIN public.inventories i ON 
    s.id = i.store_id 
    AND i.product_id = p_product_id
    AND i.company_id = v_product_company_id
  WHERE s.company_id = v_product_company_id
    AND s.active = true;  -- Solo sucursales activas

  RETURN COALESCE(v_stock_by_store, jsonb_build_array());
END;
$$;


--
-- Name: FUNCTION get_public_web_product_stock_by_store(p_product_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_public_web_product_stock_by_store(p_product_id uuid) IS 'Retorna stock desglosado por sucursal para un producto específico (PÚBLICO).
NO requiere autenticación. Retorna array JSON con store_id, store_name y qty.';


--
-- Name: get_public_web_products_catalog(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_public_web_products_catalog() RETURNS TABLE(id uuid, sku text, barcode text, name text, category text, sale_price_usd numeric, price_internacional_usd numeric, price_nacional_usd numeric, tax_rate numeric, active boolean, created_at timestamp with time zone, updated_at timestamp with time zone, total_stock integer, web_image_url text, web_visible boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    p.id,
    p.sku,
    p.barcode,
    p.name,
    p.category,

    -- sale_price_usd = alias de price_nacional_usd (retrocompatibilidad). Redondeo Base 1.
    ROUND(CASE
      WHEN ss.id IS NULL THEN p.sale_price_usd
      WHEN COALESCE(ss.web_adjustment_method, 'RATE') = 'PERCENTAGE' THEN
        p.sale_price_usd * (1 + COALESCE(ss.web_tax_percentage, 0) / 100)
      WHEN ss.web_adjustment_rate IS NULL OR ss.manual_bcv_rate IS NULL OR ss.manual_bcv_rate = 0 THEN p.sale_price_usd
      ELSE p.sale_price_usd * (ss.web_adjustment_rate / NULLIF(ss.manual_bcv_rate, 0))
    END)::numeric(15,2) AS sale_price_usd,

    -- price_internacional_usd: POS original, decimales intactos
    p.sale_price_usd::numeric(15,2) AS price_internacional_usd,

    -- price_nacional_usd: inflado + redondeo al entero más cercano (Base 1)
    ROUND(CASE
      WHEN ss.id IS NULL THEN p.sale_price_usd
      WHEN COALESCE(ss.web_adjustment_method, 'RATE') = 'PERCENTAGE' THEN
        p.sale_price_usd * (1 + COALESCE(ss.web_tax_percentage, 0) / 100)
      WHEN ss.web_adjustment_rate IS NULL OR ss.manual_bcv_rate IS NULL OR ss.manual_bcv_rate = 0 THEN p.sale_price_usd
      ELSE p.sale_price_usd * (ss.web_adjustment_rate / NULLIF(ss.manual_bcv_rate, 0))
    END)::numeric(15,2) AS price_nacional_usd,

    p.tax_rate,
    p.active,
    p.created_at,
    GREATEST(p.updated_at, COALESCE(wpm.updated_at, p.updated_at)) AS updated_at,
    COALESCE(SUM(i.qty), 0)::INTEGER AS total_stock,
    wpm.image_url AS web_image_url,
    CASE 
      WHEN wpm.image_url IS NULL OR wpm.image_url = '' THEN false
      ELSE COALESCE(wpm.visible, false)
    END AS web_visible
  FROM public.products p
  LEFT JOIN public.inventories i ON p.id = i.product_id
  LEFT JOIN public.web_product_metadata wpm ON p.id = wpm.product_id
  LEFT JOIN public.system_settings ss ON ss.company_id = p.company_id
  WHERE p.active = true
    AND wpm.image_url IS NOT NULL
    AND wpm.image_url != ''
    AND COALESCE(wpm.visible, false) = true
  GROUP BY 
    p.id, 
    p.sku, 
    p.barcode, 
    p.name, 
    p.category, 
    p.sale_price_usd, 
    p.tax_rate, 
    p.active, 
    p.created_at, 
    p.updated_at, 
    wpm.image_url, 
    wpm.visible, 
    wpm.updated_at,
    ss.id,
    ss.web_adjustment_method,
    ss.web_adjustment_rate,
    ss.manual_bcv_rate,
    ss.web_tax_percentage
  ORDER BY p.name;
END;
$$;


--
-- Name: FUNCTION get_public_web_products_catalog(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_public_web_products_catalog() IS 'Catálogo PÚBLICO. price_internacional_usd = POS (decimales intactos). price_nacional_usd = inflado + ROUND al entero (Base 1). sale_price_usd = alias de price_nacional_usd.';


--
-- Name: get_sales_history_v2(uuid, uuid, timestamp with time zone, timestamp with time zone, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_sales_history_v2(p_company_id uuid DEFAULT NULL::uuid, p_store_id uuid DEFAULT NULL::uuid, p_date_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_date_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_category text DEFAULT NULL::text, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0) RETURNS SETOF jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_user_company_id UUID;
BEGIN
    SELECT company_id INTO v_user_company_id
    FROM public.users
    WHERE auth_user_id = auth.uid()
    LIMIT 1;

    IF v_user_company_id IS NULL THEN RETURN; END IF;

    RETURN QUERY
    WITH sales_page AS (
        SELECT s.*
        FROM public.sales s
        WHERE s.company_id = COALESCE(p_company_id, v_user_company_id)
          AND (p_store_id IS NULL OR s.store_id = p_store_id)
          AND (p_date_from IS NULL OR s.created_at >= p_date_from)
          AND (p_date_to IS NULL OR s.created_at <= p_date_to)
          AND (
            p_category IS NULL
            OR p_category = 'all'
            OR EXISTS (
              SELECT 1
              FROM public.sale_items si
              LEFT JOIN public.products p ON p.id = si.product_id
              WHERE si.sale_id = s.id
                AND p.category = p_category
            )
          )
        ORDER BY s.created_at DESC
        LIMIT p_limit
        OFFSET p_offset
    )
    SELECT jsonb_build_object(
        'id', sp.id,
        'invoice_number', sp.invoice_number,
        'created_at', sp.created_at,
        'created_at_fmt', to_char((sp.created_at AT TIME ZONE 'America/Caracas'), 'DD/MM/YYYY, HH24:MI'),
        'client_name', COALESCE(NULLIF(sp.customer_name, ''), 'Cliente General'),
        'client_doc', COALESCE(sp.customer_id_number, ''),
        'store_id', sp.store_id,
        'store_name', COALESCE(st.name, 'Tienda Principal'),
        'cashier_id', sp.cashier_id,
        'cashier_name', COALESCE(u.name, u.email, 'Cajero'),
        'total_usd', sp.total_usd,
        'subtotal_usd', COALESCE(sp.subtotal_usd, sp.total_usd),
        'tax_amount_usd', COALESCE(sp.tax_amount_usd, 0),
        'bcv_rate_used', COALESCE(sp.bcv_rate_used, 41.73),
        'total_bs', CASE
            WHEN sp.total_bs IS NOT NULL AND sp.total_bs > 0.01 THEN sp.total_bs
            WHEN sp.total_usd > 0 THEN ROUND(sp.total_usd * COALESCE(sp.bcv_rate_used, 1), 2)
            ELSE 0
        END,
        'krece_enabled', COALESCE(sp.krece_enabled, false),
        'krece_initial_amount_usd', COALESCE(sp.krece_initial_amount_usd, 0),
        'krece_financed_amount_usd', COALESCE(sp.krece_financed_amount_usd, 0),
        'krece_initial_percentage', CASE
            WHEN sp.total_usd > 0 AND sp.krece_initial_amount_usd > 0 THEN ROUND((sp.krece_initial_amount_usd / sp.total_usd) * 100, 0)
            ELSE 0
        END,
        'krece_initial_amount_bs', COALESCE(
            sp.krece_initial_amount_bs,
            CASE
                WHEN sp.krece_initial_amount_bs IS NULL AND sp.krece_initial_amount_usd > 0
                THEN sp.krece_initial_amount_usd * COALESCE(sp.bcv_rate_used, 41.73)
                ELSE 0
            END
        ),
        'krece_financed_amount_bs', COALESCE(
            sp.krece_financed_amount_bs,
            CASE
                WHEN sp.krece_financed_amount_bs IS NULL AND sp.krece_financed_amount_usd > 0
                THEN sp.krece_financed_amount_usd * COALESCE(sp.bcv_rate_used, 41.73)
                ELSE 0
            END
        ),
        'cashea_enabled', COALESCE(sp.cashea_enabled, false),
        'cashea_initial_amount_usd', COALESCE(sp.cashea_initial_amount_usd, 0),
        'cashea_financed_amount_usd', COALESCE(sp.cashea_financed_amount_usd, 0),
        'cashea_initial_percentage', CASE
            WHEN sp.total_usd > 0 AND sp.cashea_initial_amount_usd > 0 THEN ROUND((sp.cashea_initial_amount_usd / sp.total_usd) * 100, 0)
            ELSE 0
        END,
        'cashea_initial_amount_bs', COALESCE(
            sp.cashea_initial_amount_bs,
            CASE
                WHEN sp.cashea_initial_amount_bs IS NULL AND sp.cashea_initial_amount_usd > 0
                THEN sp.cashea_initial_amount_usd * COALESCE(sp.bcv_rate_used, 41.73)
                ELSE 0
            END
        ),
        'cashea_financed_amount_bs', COALESCE(
            sp.cashea_financed_amount_bs,
            CASE
                WHEN sp.cashea_financed_amount_bs IS NULL AND sp.cashea_financed_amount_usd > 0
                THEN sp.cashea_financed_amount_usd * COALESCE(sp.bcv_rate_used, 41.73)
                ELSE 0
            END
        ),
        'payment_method', CASE
            WHEN sp.payment_method = 'cash_usd' THEN 'Efectivo USD'
            WHEN sp.payment_method = 'zelle' THEN 'Zelle'
            WHEN sp.payment_method = 'pago_movil' THEN 'Pago Móvil'
            WHEN sp.payment_method = 'pos' OR sp.payment_method = 'card' THEN 'Punto de Venta'
            WHEN sp.payment_method = 'biopago' THEN 'Biopago'
            WHEN sp.payment_method = 'transfer_bs' THEN 'Transferencia Bs'
            ELSE sp.payment_method
        END,
        'financing_label', CASE
            WHEN COALESCE(sp.krece_enabled, false) = true THEN
                'KRECE ' || COALESCE(
                    sp.krece_initial_percentage::TEXT,
                    CASE
                        WHEN sp.total_usd > 0 AND sp.krece_initial_amount_usd > 0
                        THEN ROUND((sp.krece_initial_amount_usd / sp.total_usd) * 100, 0)::TEXT
                        ELSE '0'
                    END
                ) || '%'
            WHEN COALESCE(sp.cashea_enabled, false) = true THEN 'CASHEA'
            ELSE 'CONTADO'
        END,
        'is_mixed_payment', COALESCE(sp.is_mixed_payment, false),
        'notes', sp.notes,
        'items', COALESCE((
            SELECT jsonb_agg(jsonb_build_object(
                'sku', COALESCE(NULLIF(si.product_sku, ''), NULLIF(si.product_sku, 'N/A'), p.sku, p.barcode, 'N/A'),
                'name', si.product_name,
                'qty', si.qty,
                'price', si.price_usd,
                'subtotal', si.subtotal_usd,
                'category', p.category
            ))
            FROM public.sale_items si
            LEFT JOIN public.products p ON si.product_id = p.id
            WHERE si.sale_id = sp.id
        ), '[]'::jsonb)
    )
    FROM sales_page sp
    LEFT JOIN public.stores st ON sp.store_id = st.id
    LEFT JOIN public.users u ON sp.cashier_id = u.id;

EXCEPTION
    WHEN OTHERS THEN
        RETURN NEXT jsonb_build_object('error', true, 'message', SQLERRM);
END;
$$;


--
-- Name: get_sales_metadata_v2(uuid, uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_sales_metadata_v2(p_company_id uuid DEFAULT NULL::uuid, p_store_id uuid DEFAULT NULL::uuid, p_date_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_date_to timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_user_company_id UUID;
    v_total_count INTEGER;
    v_total_amount_usd NUMERIC;
    v_total_amount_bs NUMERIC;
    v_category_stats JSONB;
BEGIN
    -- 1. Seguridad
    SELECT company_id INTO v_user_company_id
    FROM public.users
    WHERE auth_user_id = auth.uid()
    LIMIT 1;

    IF v_user_company_id IS NULL THEN 
        RETURN jsonb_build_object('error', true, 'message', 'Usuario no autenticado');
    END IF;

    -- 2. Contar total de ventas que cumplen filtros
    SELECT COUNT(*)
    INTO v_total_count
    FROM public.sales s
    WHERE s.company_id = COALESCE(p_company_id, v_user_company_id)
    AND (p_store_id IS NULL OR s.store_id = p_store_id)
    AND (p_date_from IS NULL OR s.created_at >= p_date_from)
    AND (p_date_to IS NULL OR s.created_at <= p_date_to);

    -- 3. Calcular total USD y BS
    SELECT 
        COALESCE(SUM(s.total_usd), 0),
        COALESCE(SUM(
            CASE
                WHEN s.total_bs IS NOT NULL AND s.total_bs > 0.01 THEN s.total_bs
                WHEN s.total_usd > 0 THEN s.total_usd * COALESCE(s.bcv_rate_used, 41.73)
                ELSE 0
            END
        ), 0)
    INTO v_total_amount_usd, v_total_amount_bs
    FROM public.sales s
    WHERE s.company_id = COALESCE(p_company_id, v_user_company_id)
    AND (p_store_id IS NULL OR s.store_id = p_store_id)
    AND (p_date_from IS NULL OR s.created_at >= p_date_from)
    AND (p_date_to IS NULL OR s.created_at <= p_date_to);

    -- 4. Calcular estadísticas por categoría desde TODAS las ventas filtradas
    SELECT jsonb_build_object(
        'phones', jsonb_build_object(
            'units', COALESCE(SUM(CASE WHEN p.category = 'phones' THEN si.qty ELSE 0 END), 0),
            'amount_usd', COALESCE(SUM(CASE WHEN p.category = 'phones' THEN si.subtotal_usd ELSE 0 END), 0),
            'amount_bs', COALESCE(SUM(CASE WHEN p.category = 'phones' THEN si.subtotal_usd * COALESCE(s.bcv_rate_used, 41.73) ELSE 0 END), 0)
        ),
        'accessories', jsonb_build_object(
            'units', COALESCE(SUM(CASE WHEN p.category = 'accessories' THEN si.qty ELSE 0 END), 0),
            'amount_usd', COALESCE(SUM(CASE WHEN p.category = 'accessories' THEN si.subtotal_usd ELSE 0 END), 0),
            'amount_bs', COALESCE(SUM(CASE WHEN p.category = 'accessories' THEN si.subtotal_usd * COALESCE(s.bcv_rate_used, 41.73) ELSE 0 END), 0)
        ),
        'technical_service', jsonb_build_object(
            'units', COALESCE(SUM(CASE WHEN p.category = 'technical_service' THEN si.qty ELSE 0 END), 0),
            'amount_usd', COALESCE(SUM(CASE WHEN p.category = 'technical_service' THEN si.subtotal_usd ELSE 0 END), 0),
            'amount_bs', COALESCE(SUM(CASE WHEN p.category = 'technical_service' THEN si.subtotal_usd * COALESCE(s.bcv_rate_used, 41.73) ELSE 0 END), 0)
        )
    )
    INTO v_category_stats
    FROM public.sales s
    INNER JOIN public.sale_items si ON s.id = si.sale_id
    LEFT JOIN public.products p ON si.product_id = p.id
    WHERE s.company_id = COALESCE(p_company_id, v_user_company_id)
    AND (p_store_id IS NULL OR s.store_id = p_store_id)
    AND (p_date_from IS NULL OR s.created_at >= p_date_from)
    AND (p_date_to IS NULL OR s.created_at <= p_date_to);

    -- 5. Retornar metadatos
    RETURN jsonb_build_object(
        'total_count', v_total_count,
        'total_amount_usd', v_total_amount_usd,
        'total_amount_bs', v_total_amount_bs,
        'average_amount_usd', CASE WHEN v_total_count > 0 THEN v_total_amount_usd / v_total_count ELSE 0 END,
        'category_stats', COALESCE(v_category_stats, jsonb_build_object(
            'phones', jsonb_build_object('units', 0, 'amount_usd', 0, 'amount_bs', 0),
            'accessories', jsonb_build_object('units', 0, 'amount_usd', 0, 'amount_bs', 0),
            'technical_service', jsonb_build_object('units', 0, 'amount_usd', 0, 'amount_bs', 0)
        ))
    );

EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object('error', true, 'message', SQLERRM);
END;
$$;


--
-- Name: FUNCTION get_sales_metadata_v2(p_company_id uuid, p_store_id uuid, p_date_from timestamp with time zone, p_date_to timestamp with time zone); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_sales_metadata_v2(p_company_id uuid, p_store_id uuid, p_date_from timestamp with time zone, p_date_to timestamp with time zone) IS 'RPC que retorna metadatos de ventas (totales, conteos, estadísticas por categoría) 
sin retornar las ventas completas. Útil para calcular totalizaciones correctas cuando 
hay filtros de fecha, tienda y paginación. Respeta los mismos filtros que get_sales_history_v2.';


--
-- Name: get_sales_metadata_v2(uuid, uuid, timestamp with time zone, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_sales_metadata_v2(p_company_id uuid DEFAULT NULL::uuid, p_store_id uuid DEFAULT NULL::uuid, p_date_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_date_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_category text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_user_company_id UUID;
    v_total_count INTEGER;
    v_total_amount_usd NUMERIC;
    v_total_amount_bs NUMERIC;
    v_category_stats JSONB;
BEGIN
    SELECT company_id INTO v_user_company_id
    FROM public.users
    WHERE auth_user_id = auth.uid()
    LIMIT 1;

    IF v_user_company_id IS NULL THEN
        RETURN jsonb_build_object('error', true, 'message', 'Usuario no autenticado');
    END IF;

    SELECT COUNT(*)
    INTO v_total_count
    FROM public.sales s
    WHERE s.company_id = COALESCE(p_company_id, v_user_company_id)
      AND (p_store_id IS NULL OR s.store_id = p_store_id)
      AND (p_date_from IS NULL OR s.created_at >= p_date_from)
      AND (p_date_to IS NULL OR s.created_at <= p_date_to)
      AND (
        p_category IS NULL
        OR p_category = 'all'
        OR EXISTS (
          SELECT 1
          FROM public.sale_items si
          LEFT JOIN public.products p ON p.id = si.product_id
          WHERE si.sale_id = s.id
            AND p.category = p_category
        )
      );

    SELECT
        COALESCE(SUM(s.total_usd), 0),
        COALESCE(SUM(
            CASE
                WHEN s.total_bs IS NOT NULL AND s.total_bs > 0.01 THEN s.total_bs
                WHEN s.total_usd > 0 THEN s.total_usd * COALESCE(s.bcv_rate_used, 41.73)
                ELSE 0
            END
        ), 0)
    INTO v_total_amount_usd, v_total_amount_bs
    FROM public.sales s
    WHERE s.company_id = COALESCE(p_company_id, v_user_company_id)
      AND (p_store_id IS NULL OR s.store_id = p_store_id)
      AND (p_date_from IS NULL OR s.created_at >= p_date_from)
      AND (p_date_to IS NULL OR s.created_at <= p_date_to)
      AND (
        p_category IS NULL
        OR p_category = 'all'
        OR EXISTS (
          SELECT 1
          FROM public.sale_items si
          LEFT JOIN public.products p ON p.id = si.product_id
          WHERE si.sale_id = s.id
            AND p.category = p_category
        )
      );

    SELECT jsonb_build_object(
        'phones', jsonb_build_object(
            'units', COALESCE(SUM(CASE WHEN p.category = 'phones' THEN si.qty ELSE 0 END), 0),
            'amount_usd', COALESCE(SUM(CASE WHEN p.category = 'phones' THEN si.subtotal_usd ELSE 0 END), 0),
            'amount_bs', COALESCE(SUM(CASE WHEN p.category = 'phones' THEN si.subtotal_usd * COALESCE(s.bcv_rate_used, 41.73) ELSE 0 END), 0)
        ),
        'accessories', jsonb_build_object(
            'units', COALESCE(SUM(CASE WHEN p.category = 'accessories' THEN si.qty ELSE 0 END), 0),
            'amount_usd', COALESCE(SUM(CASE WHEN p.category = 'accessories' THEN si.subtotal_usd ELSE 0 END), 0),
            'amount_bs', COALESCE(SUM(CASE WHEN p.category = 'accessories' THEN si.subtotal_usd * COALESCE(s.bcv_rate_used, 41.73) ELSE 0 END), 0)
        ),
        'technical_service', jsonb_build_object(
            'units', COALESCE(SUM(CASE WHEN p.category = 'technical_service' THEN si.qty ELSE 0 END), 0),
            'amount_usd', COALESCE(SUM(CASE WHEN p.category = 'technical_service' THEN si.subtotal_usd ELSE 0 END), 0),
            'amount_bs', COALESCE(SUM(CASE WHEN p.category = 'technical_service' THEN si.subtotal_usd * COALESCE(s.bcv_rate_used, 41.73) ELSE 0 END), 0)
        )
    )
    INTO v_category_stats
    FROM public.sales s
    INNER JOIN public.sale_items si ON s.id = si.sale_id
    LEFT JOIN public.products p ON si.product_id = p.id
    WHERE s.company_id = COALESCE(p_company_id, v_user_company_id)
      AND (p_store_id IS NULL OR s.store_id = p_store_id)
      AND (p_date_from IS NULL OR s.created_at >= p_date_from)
      AND (p_date_to IS NULL OR s.created_at <= p_date_to)
      AND (
        p_category IS NULL
        OR p_category = 'all'
        OR p.category = p_category
      );

    RETURN jsonb_build_object(
        'total_count', v_total_count,
        'total_amount_usd', v_total_amount_usd,
        'total_amount_bs', v_total_amount_bs,
        'average_amount_usd', CASE WHEN v_total_count > 0 THEN v_total_amount_usd / v_total_count ELSE 0 END,
        'category_stats', COALESCE(v_category_stats, jsonb_build_object(
            'phones', jsonb_build_object('units', 0, 'amount_usd', 0, 'amount_bs', 0),
            'accessories', jsonb_build_object('units', 0, 'amount_usd', 0, 'amount_bs', 0),
            'technical_service', jsonb_build_object('units', 0, 'amount_usd', 0, 'amount_bs', 0)
        ))
    );
EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object('error', true, 'message', SQLERRM);
END;
$$;


--
-- Name: get_stock_matrix_by_store(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_stock_matrix_by_store(p_company_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_company_id UUID;
  v_matrix JSONB;
BEGIN
  -- Obtener company_id del usuario si no se proporciona
  IF p_company_id IS NULL THEN
    v_company_id := public.get_user_company_id();
  ELSE
    v_company_id := p_company_id;
  END IF;

  -- Validar que company_id no sea NULL
  IF v_company_id IS NULL THEN
    RETURN jsonb_build_object(
      'error', true,
      'message', 'Company ID is required'
    );
  END IF;

  -- Construir matriz usando CTEs para evitar agregaciones anidadas
  WITH products_by_company AS (
    -- CTE 1: Productos filtrados por company_id y active
    SELECT 
      id,
      category,
      cost_usd,
      sale_price_usd
    FROM public.products
    WHERE company_id = v_company_id
      AND active = true
  ),
  stores_by_company AS (
    -- CTE 2: Tiendas filtradas por company_id y active
    SELECT 
      id,
      name
    FROM public.stores
    WHERE company_id = v_company_id
      AND active = true
  ),
  inventory_agg AS (
    -- CTE 3: Agregar inventarios por (store_id, product_id)
    SELECT 
      inv.store_id,
      inv.product_id,
      inv.qty,
      inv.min_qty,
      p.category,
      p.cost_usd,
      p.sale_price_usd,
      inv.qty * p.cost_usd AS cost_value,
      inv.qty * p.sale_price_usd AS retail_value
    FROM public.inventories inv
    INNER JOIN products_by_company p ON inv.product_id = p.id
    WHERE inv.company_id = v_company_id
  ),
  category_agg AS (
    -- CTE 4: Agrupar por (store_id, category)
    SELECT 
      store_id,
      COALESCE(category, 'Sin Categoría') AS category_name,
      COALESCE(SUM(qty), 0) AS stock_qty,
      COALESCE(SUM(cost_value), 0) AS value_cost,
      COALESCE(SUM(retail_value), 0) AS value_retail,
      COUNT(DISTINCT product_id) AS products_count,
      COUNT(DISTINCT CASE 
        WHEN qty > 0 AND qty <= min_qty 
        THEN product_id 
      END) AS low_stock_count
    FROM inventory_agg
    GROUP BY store_id, COALESCE(category, 'Sin Categoría')
  ),
  store_totals AS (
    -- CTE 5: Totales por tienda
    SELECT 
      store_id,
      COUNT(DISTINCT product_id) AS total_items,
      COALESCE(SUM(qty), 0) AS total_stock_quantity
    FROM inventory_agg
    GROUP BY store_id
  )
  -- SELECT FINAL: Construir JSON estructurado sin anidaciones
  SELECT jsonb_agg(
    jsonb_build_object(
      'store_id', s.id,
      'store_name', s.name,
      'total_items', COALESCE(st.total_items, 0),
      'total_stock_quantity', COALESCE(st.total_stock_quantity, 0),
      'categories', (
        SELECT COALESCE(jsonb_agg(
          jsonb_build_object(
            'category_name', ca.category_name,
            'stock_qty', ca.stock_qty,
            'value_cost', ca.value_cost,
            'value_retail', ca.value_retail,
            'products_count', ca.products_count,
            'low_stock_count', ca.low_stock_count
          )
          ORDER BY ca.value_retail DESC
        ), '[]'::jsonb)
        FROM category_agg ca
        WHERE ca.store_id = s.id
      )
    )
    ORDER BY s.name
  )
  INTO v_matrix
  FROM stores_by_company s
  LEFT JOIN store_totals st ON s.id = st.store_id;

  RETURN jsonb_build_object(
    'matrix', COALESCE(v_matrix, '[]'::jsonb),
    'generated_at', NOW()
  );
EXCEPTION
  WHEN OTHERS THEN
    RETURN jsonb_build_object(
      'error', true,
      'message', SQLERRM,
      'code', SQLSTATE
    );
END;
$$;


--
-- Name: get_store_inventory_stats(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_store_inventory_stats(p_store_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_company_id UUID;
    v_stats JSONB;
BEGIN
    -- Obtener company_id del usuario
    SELECT company_id INTO v_company_id
    FROM public.users
    WHERE auth_user_id = auth.uid()
    LIMIT 1;

    IF v_company_id IS NULL THEN
        RAISE EXCEPTION 'Usuario no está vinculado a una compañía.';
    END IF;

    -- Verificar que la tienda pertenece a la compañía del usuario
    IF NOT EXISTS (
        SELECT 1 FROM public.stores
        WHERE id = p_store_id AND company_id = v_company_id AND active = true
    ) THEN
        RAISE EXCEPTION 'Tienda no encontrada o no pertenece a tu compañía.';
    END IF;

    -- Calcular estadísticas SOLO para productos activos
    SELECT jsonb_build_object(
        'store_id', p_store_id,
        'total_products', COUNT(DISTINCT i.product_id) FILTER (WHERE p.active = true),
        'total_stock', COALESCE(SUM(i.qty) FILTER (WHERE p.active = true), 0),
        'total_value', COALESCE(SUM(i.qty * COALESCE(p.sale_price_usd, 0)) FILTER (WHERE p.active = true), 0),
        'low_stock_count', COUNT(DISTINCT i.product_id) FILTER (
            WHERE p.active = true 
            AND i.qty <= i.min_qty 
            AND i.qty > 0
        ),
        'out_of_stock_count', COUNT(DISTINCT i.product_id) FILTER (
            WHERE p.active = true 
            AND i.qty = 0
        )
    ) INTO v_stats
    FROM public.inventories i
    INNER JOIN public.products p ON i.product_id = p.id
    WHERE i.store_id = p_store_id
    AND i.company_id = v_company_id
    AND p.active = true;  -- ⚠️ FILTRO CRÍTICO: Solo productos activos

    RETURN v_stats;
END;
$$;


--
-- Name: FUNCTION get_store_inventory_stats(p_store_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_store_inventory_stats(p_store_id uuid) IS 'Devuelve estadísticas de inventario para una tienda específica. 
IMPORTANTE: Solo incluye productos activos (active = true).';


