--
-- Name: get_web_product_stock(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_web_product_stock(p_product_id uuid) RETURNS integer
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    AS $$
DECLARE
  v_company_id UUID;
  v_total_stock INTEGER;
BEGIN
  -- Obtener company_id del usuario
  SELECT company_id INTO v_company_id
  FROM public.users
  WHERE auth_user_id = auth.uid()
  LIMIT 1;

  IF v_company_id IS NULL THEN
    RETURN 0;
  END IF;

  -- Calcular stock total sumando todas las sucursales
  SELECT COALESCE(SUM(qty), 0) INTO v_total_stock
  FROM public.inventories
  WHERE product_id = p_product_id
    AND company_id = v_company_id;

  RETURN v_total_stock;
END;
$$;


--
-- Name: FUNCTION get_web_product_stock(p_product_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_web_product_stock(p_product_id uuid) IS 'Calcula stock total de un producto sumando todas las sucursales. 
Optimizado para consultas rápidas desde el módulo web.';


--
-- Name: get_web_product_stock_by_store(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_web_product_stock_by_store(p_product_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    AS $$
DECLARE
  v_company_id UUID;
  v_stock_by_store JSONB;
BEGIN
  -- Obtener company_id del usuario autenticado
  SELECT company_id INTO v_company_id
  FROM public.users
  WHERE auth_user_id = auth.uid()
  LIMIT 1;

  IF v_company_id IS NULL THEN
    RETURN jsonb_build_array();  -- Retornar array vacío si no hay company_id
  END IF;

  -- Construir array JSON con stock por sucursal
  SELECT jsonb_agg(
    jsonb_build_object(
      'store_id', s.id,
      'store_name', s.name,
      'qty', COALESCE(i.qty, 0)
    )
    ORDER BY s.name
  ) INTO v_stock_by_store
  FROM public.stores s
  LEFT JOIN public.inventories i ON 
    s.id = i.store_id 
    AND i.product_id = p_product_id
    AND i.company_id = v_company_id
  WHERE s.company_id = v_company_id
    AND s.active = true;  -- Solo sucursales activas

  RETURN COALESCE(v_stock_by_store, jsonb_build_array());
END;
$$;


--
-- Name: FUNCTION get_web_product_stock_by_store(p_product_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_web_product_stock_by_store(p_product_id uuid) IS 'Retorna stock desglosado por sucursal para un producto específico.
Requiere autenticación. Retorna array JSON con store_id, store_name y qty.';


--
-- Name: get_web_products_catalog(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_web_products_catalog() RETURNS TABLE(id uuid, sku text, barcode text, name text, category text, sale_price_usd numeric, tax_rate numeric, active boolean, created_at timestamp with time zone, updated_at timestamp with time zone, total_stock integer, web_image_url text, web_visible boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    AS $$
DECLARE
  v_company_id UUID;
BEGIN
  -- Obtener company_id del usuario autenticado
  SELECT company_id INTO v_company_id
  FROM public.users
  WHERE auth_user_id = auth.uid()
  LIMIT 1;

  IF v_company_id IS NULL THEN
    RETURN;  -- No retornar nada si no hay company_id
  END IF;

  -- Retornar productos con metadatos web, SIN cost_usd
  RETURN QUERY
  SELECT 
    p.id,
    p.sku,
    p.barcode,
    p.name,
    p.category,
    p.sale_price_usd,  -- ✅ Incluido
    p.tax_rate,
    p.active,
    p.created_at,
    -- ✅ Usar el updated_at más reciente entre products y web_product_metadata
    -- Esto asegura que si solo se actualiza la imagen, el updated_at refleje el cambio
    GREATEST(p.updated_at, COALESCE(wpm.updated_at, p.updated_at)) AS updated_at,
    -- ❌ p.cost_usd EXCLUIDO explícitamente
    COALESCE(SUM(i.qty), 0)::INTEGER AS total_stock,
    wpm.image_url AS web_image_url,
    -- ✅ REGLA: Si no hay imagen, visible = false. Si hay imagen, usar el valor de wpm.visible
    CASE 
      WHEN wpm.image_url IS NULL OR wpm.image_url = '' THEN false
      ELSE COALESCE(wpm.visible, false)
    END AS web_visible
  FROM public.products p
  LEFT JOIN public.inventories i ON p.id = i.product_id AND i.company_id = v_company_id
  LEFT JOIN public.web_product_metadata wpm ON p.id = wpm.product_id
  WHERE p.company_id = v_company_id
    AND p.active = true
  GROUP BY 
    p.id, 
    p.sku, 
    p.barcode, 
    p.name, 
    p.category, 
    p.sale_price_usd, 
    p.tax_rate, 
    p.active, 
    p.created_at, 
    p.updated_at, 
    wpm.image_url, 
    wpm.visible, 
    wpm.updated_at
  ORDER BY p.name;
END;
$$;


--
-- Name: FUNCTION get_web_products_catalog(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_web_products_catalog() IS 'Catálogo de productos para web pública. EXCLUYE cost_usd y otros datos sensibles. 
Incluye stock total y metadatos web. Solo productos activos.';


--
-- Name: handle_new_user(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_new_user() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_role TEXT;
  v_company_id UUID;
  v_assigned_store_id UUID;
  v_name TEXT;
  v_email TEXT;
  v_existing_profile_id UUID;
BEGIN
  -- Extract email from the new auth user
  v_email := NEW.email;
  
  -- Check if a profile already exists for this auth_user_id
  -- This prevents duplicate profiles if the trigger fires multiple times
  SELECT id INTO v_existing_profile_id
  FROM public.users
  WHERE auth_user_id = NEW.id
  LIMIT 1;
  
  -- If profile already exists, update it with the latest auth_user_id (in case it was NULL)
  IF v_existing_profile_id IS NOT NULL THEN
    UPDATE public.users
    SET 
      auth_user_id = NEW.id,
      email = COALESCE(v_email, email),
      updated_at = NOW()
    WHERE id = v_existing_profile_id;
    
    RAISE NOTICE 'Profile already exists for user % (%), updated auth_user_id', NEW.id, v_email;
    RETURN NEW;
  END IF;
  
  -- Check if a profile exists with the same email but different auth_user_id
  -- This handles the case where a profile was created manually before auth user was created
  SELECT id INTO v_existing_profile_id
  FROM public.users
  WHERE email = v_email
    AND (auth_user_id IS NULL OR auth_user_id != NEW.id)
  LIMIT 1;
  
  -- If found, link the existing profile to this auth user
  IF v_existing_profile_id IS NOT NULL THEN
    UPDATE public.users
    SET 
      auth_user_id = NEW.id,
      updated_at = NOW()
    WHERE id = v_existing_profile_id;
    
    RAISE NOTICE 'Linked existing profile to auth user % (%)', NEW.id, v_email;
    RETURN NEW;
  END IF;
  
  -- Extract metadata from raw_user_meta_data
  -- Role: default to 'cashier' if not provided
  v_role := COALESCE(
    NEW.raw_user_meta_data->>'role',
    'cashier'
  );
  
  -- Validate role is one of the allowed values
  IF v_role NOT IN ('admin', 'manager', 'cashier', 'master_admin') THEN
    v_role := 'cashier'; -- Default to cashier if invalid role
    RAISE WARNING 'Invalid role in metadata, defaulting to cashier for user %', v_email;
  END IF;
  
  -- Company ID: REQUIRED - must be provided in metadata
  -- If not provided, we cannot create the profile (this is a critical field)
  v_company_id := (NEW.raw_user_meta_data->>'company_id')::UUID;
  
  IF v_company_id IS NULL THEN
    RAISE WARNING 'No company_id provided in metadata for user %. Profile creation skipped. User must be created via admin panel or RPC.', v_email;
    -- Return NEW to allow auth user creation, but skip profile creation
    -- The profile can be created later via admin panel or RPC
    RETURN NEW;
  END IF;
  
  -- Assigned Store ID: Optional (nullable)
  IF NEW.raw_user_meta_data->>'assigned_store_id' IS NOT NULL THEN
    v_assigned_store_id := (NEW.raw_user_meta_data->>'assigned_store_id')::UUID;
  ELSE
    v_assigned_store_id := NULL;
  END IF;
  
  -- Name: Extract from metadata or derive from email
  v_name := COALESCE(
    NEW.raw_user_meta_data->>'name',
    NEW.raw_user_meta_data->>'user_name',
    split_part(v_email, '@', 1) -- Fallback: use email prefix as name
  );
  
  -- Insert the new profile into public.users
    auth_user_id,
    email,
    name,
    role,
    company_id,
    assigned_store_id,
    active,
    created_at,
    updated_at
  ) VALUES (
    NEW.id,                    -- auth_user_id from auth.users
    v_email,                   -- email from auth.users
    v_name,                    -- name from metadata or email
    v_role,                    -- role from metadata (default: 'cashier')
    v_company_id,              -- company_id from metadata (REQUIRED)
    v_assigned_store_id,       -- assigned_store_id from metadata (nullable)
    true,                      -- active defaults to true
    NOW(),                     -- created_at
    NOW()                      -- updated_at
  )
  ON CONFLICT (auth_user_id) DO UPDATE
  SET
    email = EXCLUDED.email,
    name = EXCLUDED.name,
    role = EXCLUDED.role,
    company_id = EXCLUDED.company_id,
    assigned_store_id = COALESCE(EXCLUDED.assigned_store_id, public.users.assigned_store_id),
    active = true,
    updated_at = NOW();
  
  RAISE NOTICE 'Profile created successfully for user % (%) with role %', NEW.id, v_email, v_role;
  
  RETURN NEW;
  
EXCEPTION
  WHEN OTHERS THEN
    -- Log the error but don't prevent auth user creation
    RAISE WARNING 'Error creating profile for user % (%): %', NEW.id, v_email, SQLERRM;
    -- Return NEW to allow auth user creation to proceed
    -- The profile can be created later via admin panel or RPC
    RETURN NEW;
END;
$$;


--
-- Name: FUNCTION handle_new_user(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.handle_new_user() IS 'Automatically creates a profile in public.users when a new user is created in auth.users. 
Extracts role, company_id, and assigned_store_id from raw_user_meta_data. 
Defaults role to cashier if not provided. Requires company_id in metadata to create profile.';


--
-- Name: initialize_inventories_for_new_store(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.initialize_inventories_for_new_store() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_batch_size INTEGER := 1000;
  v_total_products INTEGER;
  v_processed INTEGER := 0;
  v_admin_user_id uuid;
BEGIN
  -- Obtener ID de admin para movimientos
  SELECT id INTO v_admin_user_id
  FROM public.users
  WHERE company_id = NEW.company_id AND role = 'admin'
  LIMIT 1;

  -- Contar productos activos
  SELECT COUNT(*) INTO v_total_products
  FROM products
  WHERE company_id = NEW.company_id AND active = true;
  
  -- Si hay muchos productos, procesar en batches para evitar timeout
  IF v_total_products > 5000 THEN
    -- Procesar en batches
    FOR v_processed IN 0..v_total_products BY v_batch_size LOOP
      -- Insertar inventarios en batch
      SELECT NEW.company_id, NEW.id, id, 0, 5
      FROM products
      WHERE company_id = NEW.company_id 
        AND active = true
        AND id NOT IN (
          SELECT product_id 
          FROM inventories 
          WHERE store_id = NEW.id AND company_id = NEW.company_id
        )
      ORDER BY id
      LIMIT v_batch_size
      OFFSET v_processed;
    END LOOP;
  ELSE
    -- Procesamiento directo para < 5000 productos
    SELECT NEW.company_id, NEW.id, id, 0, 5
    FROM products
    WHERE company_id = NEW.company_id AND active = true;
  END IF;
  
  RETURN NEW;
END;
$$;


