--
-- Name: link_user_profile_by_email(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.link_user_profile_by_email() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_auth_user_id UUID;
  v_email TEXT;
  v_profile_id UUID;
  v_current_auth_user_id UUID;
BEGIN
  -- Obtener el auth_user_id del usuario actual
  v_auth_user_id := auth.uid();
  
  IF v_auth_user_id IS NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Usuario no autenticado'
    );
  END IF;
  
  -- Obtener email del usuario autenticado
  SELECT email INTO v_email
  FROM auth.users
  WHERE id = v_auth_user_id;
  
  IF v_email IS NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'No se pudo obtener el email del usuario'
    );
  END IF;
  
  -- Buscar perfil con el mismo email
  SELECT id, auth_user_id INTO v_profile_id, v_current_auth_user_id
  FROM public.users
  WHERE email = v_email
  LIMIT 1;
  
  IF v_profile_id IS NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'No se encontró un perfil con este email'
    );
  END IF;
  
  -- Si ya está vinculado correctamente, retornar éxito
  IF v_current_auth_user_id = v_auth_user_id THEN
    RETURN jsonb_build_object(
      'success', true,
      'message', 'El perfil ya está vinculado correctamente',
      'profile_id', v_profile_id
    );
  END IF;
  
  -- Si está vinculado a otro usuario, no permitir el cambio
  IF v_current_auth_user_id IS NOT NULL AND v_current_auth_user_id != v_auth_user_id THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Este perfil ya está vinculado a otro usuario'
    );
  END IF;
  
  -- Vincular el perfil (solo si auth_user_id es NULL o diferente)
  UPDATE public.users
  SET 
    auth_user_id = v_auth_user_id,
    updated_at = NOW()
  WHERE id = v_profile_id
    AND (auth_user_id IS NULL OR auth_user_id != v_auth_user_id);
  
  -- Verificar que se actualizó correctamente
  SELECT auth_user_id INTO v_current_auth_user_id
  FROM public.users
  WHERE id = v_profile_id;
  
  IF v_current_auth_user_id = v_auth_user_id THEN
    RETURN jsonb_build_object(
      'success', true,
      'message', 'Perfil vinculado exitosamente',
      'profile_id', v_profile_id,
      'auth_user_id', v_auth_user_id
    );
  ELSE
    RETURN jsonb_build_object(
      'success', false,
      'error', 'No se pudo vincular el perfil. Verificar permisos RLS.'
    );
  END IF;
  
EXCEPTION
  WHEN OTHERS THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', SQLERRM,
      'code', SQLSTATE
    );
END;
$$;


--
-- Name: FUNCTION link_user_profile_by_email(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.link_user_profile_by_email() IS 'Permite que un usuario autenticado vincule su auth_user_id con un perfil existente en public.users que tenga el mismo email. Útil para usuarios creados por admin que luego se registran.';


--
-- Name: log_inventory_activity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_inventory_activity() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    action_text TEXT;
    user_uuid UUID := NULL;
    details_json JSONB;
BEGIN
    -- Intenta obtener el ID del usuario autenticado (quien llama al RPC)
    BEGIN
        user_uuid := auth.uid();
    EXCEPTION WHEN OTHERS THEN
        user_uuid := NULL; -- Si es una acción del sistema
    END;

    IF (TG_OP = 'INSERT') THEN
        action_text := 'STOCK_INCREASE_INITIAL';
        details_json := jsonb_build_object(
            'store_id', NEW.store_id,
            'product_id', NEW.product_id,
            'qty_added', NEW.qty
        );
    ELSIF (TG_OP = 'UPDATE') THEN
        -- Solo loguear si la cantidad cambia
        IF (OLD.qty <> NEW.qty) THEN
            action_text := 'STOCK_ADJUSTMENT';
            
            IF (OLD.qty > NEW.qty) THEN
                action_text := 'STOCK_DECREASE_SALE_OR_TRANSFER';
            ELSIF (OLD.qty < NEW.qty) THEN
                action_text := 'STOCK_INCREASE_MANUAL_OR_TRANSFER';
            END IF;
            
            details_json := jsonb_build_object(
                'store_id', NEW.store_id,
                'product_id', NEW.product_id,
                'qty_before', OLD.qty,
                'qty_after', NEW.qty,
                'qty_change', NEW.qty - OLD.qty
            );
        ELSE
            RETURN NEW; -- No hay cambio de stock, no loguear
        END IF;
    ELSIF (TG_OP = 'DELETE') THEN
        action_text := 'INVENTORY_RECORD_DELETED';
        details_json := jsonb_build_object(
            'store_id', OLD.store_id,
            'product_id', OLD.product_id,
            'qty_at_deletion', OLD.qty
        );
    ELSE
        RETURN NULL;
    END IF;

    VALUES (user_uuid, action_text, 'inventories', COALESCE(NEW.id, OLD.id), details_json);
    RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: log_product_activity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_product_activity() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    action_text TEXT;
    user_uuid UUID := NULL;
    details_json JSONB;
BEGIN
    -- Intenta obtener el ID del usuario autenticado
    BEGIN
        user_uuid := auth.uid();
    EXCEPTION WHEN OTHERS THEN
        user_uuid := NULL;
    END;

    IF (TG_OP = 'INSERT') THEN
        action_text := 'PRODUCT_REGISTERED';
        details_json := jsonb_build_object(
            'product_name', NEW.name,
            'sale_price_usd', NEW.sale_price_usd
        );
    ELSIF (TG_OP = 'UPDATE') THEN
        action_text := 'PRODUCT_MODIFIED';
        details_json := jsonb_build_object(
            'old_name', OLD.name,
            'new_name', NEW.name,
            'old_price', OLD.sale_price_usd,
            'new_price', NEW.sale_price_usd
        );
    ELSIF (TG_OP = 'DELETE') THEN
        action_text := 'PRODUCT_DELETED';
        details_json := jsonb_build_object(
            'product_name', OLD.name,
            'product_sku', OLD.sku
        );
    ELSE
        RETURN NULL;
    END IF;

    VALUES (user_uuid, action_text, 'products', COALESCE(NEW.id, OLD.id), details_json);
    RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: process_sale(uuid, uuid, uuid, uuid, text, text, numeric, text, jsonb, text, numeric, boolean, numeric, numeric, numeric, boolean, jsonb, numeric, numeric, numeric, numeric, boolean, numeric, numeric, numeric, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.process_sale(p_company_id uuid, p_store_id uuid, p_cashier_id uuid, p_customer_id uuid DEFAULT NULL::uuid, p_payment_method text DEFAULT 'cash_usd'::text, p_customer_name text DEFAULT 'Cliente General'::text, p_bcv_rate numeric DEFAULT 41.73, p_customer_id_number text DEFAULT NULL::text, p_items jsonb DEFAULT '[]'::jsonb, p_notes text DEFAULT NULL::text, p_tax_rate numeric DEFAULT 0.16, p_krece_enabled boolean DEFAULT false, p_krece_initial_amount_usd numeric DEFAULT 0, p_krece_financed_amount_usd numeric DEFAULT 0, p_krece_initial_percentage numeric DEFAULT 0, p_is_mixed_payment boolean DEFAULT false, p_mixed_payments jsonb DEFAULT '[]'::jsonb, p_subtotal_usd numeric DEFAULT 0, p_total_bs numeric DEFAULT NULL::numeric, p_krece_initial_amount_bs numeric DEFAULT NULL::numeric, p_krece_financed_amount_bs numeric DEFAULT NULL::numeric, p_cashea_enabled boolean DEFAULT false, p_cashea_initial_amount_usd numeric DEFAULT 0, p_cashea_financed_amount_usd numeric DEFAULT 0, p_cashea_initial_percentage numeric DEFAULT 0, p_cashea_initial_amount_bs numeric DEFAULT NULL::numeric, p_cashea_financed_amount_bs numeric DEFAULT NULL::numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    new_sale_id UUID;
    item JSONB;
    v_subtotal_calculado NUMERIC := 0;
    v_total_calculado NUMERIC := 0;
    v_qty NUMERIC;
    v_price NUMERIC;
    v_product_name TEXT;
    v_product_sku TEXT;
    v_invoice_number TEXT;
    v_product_id UUID;
    v_current_stock NUMERIC;
    v_product_name_db TEXT;
    v_product_sku_db TEXT;
    v_sale_price_usd NUMERIC;
    v_total_bs_final NUMERIC;
    v_krece_initial_bs_final NUMERIC;
    v_krece_financed_bs_final NUMERIC;
    v_cashea_initial_bs_final NUMERIC;
    v_cashea_financed_bs_final NUMERIC;
    -- Variables para mensajes de auditoría
    v_product_name_mov TEXT;
    v_product_sku_mov TEXT;
    v_store_name_mov TEXT;
BEGIN
    -- 🔒 SEGURIDAD ANTI-COLGAMIENTO: Timeout de bloqueo para evitar transacciones zombie
    SET LOCAL lock_timeout = '4000ms';

    -- ✅ ELIMINACIÓN DE IVA: Anular cualquier parámetro de tax_rate que envíe el frontend
    p_tax_rate := 0;

    -- ========================================================================
    -- VALIDACIÓN DE INTEGRIDAD FINANCIERA (ACTUALIZADA: Incluye Cashea)
    -- ========================================================================
    IF (p_total_bs IS NOT NULL AND p_total_bs < 0) OR 
       (p_krece_initial_amount_bs IS NOT NULL AND p_krece_initial_amount_bs < 0) OR
       (p_krece_financed_amount_bs IS NOT NULL AND p_krece_financed_amount_bs < 0) OR
       (p_cashea_initial_amount_bs IS NOT NULL AND p_cashea_initial_amount_bs < 0) OR
       (p_cashea_financed_amount_bs IS NOT NULL AND p_cashea_financed_amount_bs < 0) THEN
        RAISE EXCEPTION 'Error de Integridad: Los montos financieros en Bolívares no pueden ser negativos.';
    END IF;

    -- 1. VALIDACIONES INICIALES
    IF p_company_id IS NULL THEN
        RAISE EXCEPTION 'company_id es requerido';
    END IF;
    
    IF p_store_id IS NULL THEN
        RAISE EXCEPTION 'store_id es requerido';
    END IF;
    
    IF p_cashier_id IS NULL THEN
        RAISE EXCEPTION 'cashier_id es requerido';
    END IF;
    
    IF p_items IS NULL OR jsonb_array_length(p_items) = 0 THEN
        RAISE EXCEPTION 'La venta debe contener al menos un item';
    END IF;

    -- 2. CÁLCULO SEGURO DEL SUBTOTAL Y VALIDACIÓN DE ITEMS
    FOR item IN SELECT * FROM jsonb_array_elements(p_items) LOOP
        v_product_id := (item->>'product_id')::UUID;
        v_price := COALESCE((item->>'price_usd')::NUMERIC, 0);
        v_qty := COALESCE((item->>'qty')::NUMERIC, 0);
        
        IF v_product_id IS NULL THEN
            RAISE EXCEPTION 'Todos los items deben tener product_id válido';
        END IF;
        
        -- ✅ CORRECCIÓN: Validar que qty > 0 (no convertir 0 a 1)
        IF v_qty <= 0 THEN 
            RAISE EXCEPTION 'La cantidad debe ser mayor a 0 para el producto %', v_product_id;
        END IF;
        
        IF v_price < 0 THEN
            RAISE EXCEPTION 'El precio no puede ser negativo para el producto %', v_product_id;
        END IF;
        
        v_subtotal_calculado := v_subtotal_calculado + (v_qty * v_price);
    END LOOP;
    
    IF v_subtotal_calculado <= 0 THEN
        v_subtotal_calculado := COALESCE(p_subtotal_usd, 0);
    END IF;

    v_total_calculado := v_subtotal_calculado;

    -- ========================================================================
    -- CÁLCULO DE VALORES EN BOLÍVARES
    -- ========================================================================
    v_total_bs_final := COALESCE(
        p_total_bs, 
        v_total_calculado * COALESCE(p_bcv_rate, 41.73)
    );

    v_krece_initial_bs_final := COALESCE(
        p_krece_initial_amount_bs,
        p_krece_initial_amount_usd * COALESCE(p_bcv_rate, 41.73)
    );

    v_krece_financed_bs_final := COALESCE(
        p_krece_financed_amount_bs,
        p_krece_financed_amount_usd * COALESCE(p_bcv_rate, 41.73)
    );

    v_cashea_initial_bs_final := COALESCE(
        p_cashea_initial_amount_bs,
        p_cashea_initial_amount_usd * COALESCE(p_bcv_rate, 41.73)
    );

    v_cashea_financed_bs_final := COALESCE(
        p_cashea_financed_amount_bs,
        p_cashea_financed_amount_usd * COALESCE(p_bcv_rate, 41.73)
    );

    -- 4. GENERAR NÚMERO DE FACTURA
    BEGIN
        v_invoice_number := generate_invoice_number(p_company_id);
    EXCEPTION
        WHEN OTHERS THEN
            v_invoice_number := 'FAC-' || to_char(now(), 'YYYYMMDD') || '-' || substr(gen_random_uuid()::text, 1, 8);
    END;

    -- 5. INSERTAR CABECERA DE VENTA
        company_id, store_id, cashier_id, customer_id, customer_name, 
        customer_id_number, bcv_rate_used, is_mixed_payment,
        subtotal_usd, total_usd, total_bs, payment_method, notes, 
        krece_enabled, 
        krece_initial_amount_usd, krece_financed_amount_usd,
        krece_initial_amount_bs, krece_financed_amount_bs,
        cashea_enabled,
        cashea_initial_amount_usd, cashea_financed_amount_usd,
        cashea_initial_percentage,
        cashea_initial_amount_bs, cashea_financed_amount_bs,
        status, tax_rate, invoice_number
    ) VALUES (
        p_company_id, p_store_id, p_cashier_id, p_customer_id, p_customer_name, 
        p_customer_id_number, COALESCE(p_bcv_rate, 0), COALESCE(p_is_mixed_payment, false),
        v_subtotal_calculado, v_total_calculado, v_total_bs_final, 
        p_payment_method, p_notes, 
        p_krece_enabled, 
        COALESCE(p_krece_initial_amount_usd, 0), COALESCE(p_krece_financed_amount_usd, 0),
        v_krece_initial_bs_final, v_krece_financed_bs_final,
        p_cashea_enabled,
        COALESCE(p_cashea_initial_amount_usd, 0), COALESCE(p_cashea_financed_amount_usd, 0),
        COALESCE(p_cashea_initial_percentage, 0),
        v_cashea_initial_bs_final, v_cashea_financed_bs_final,
        'completed', 0, v_invoice_number
    ) RETURNING id INTO new_sale_id;

    -- ========================================================================
    -- 6. PROCESAR ITEMS Y ACTUALIZAR STOCK (🔒 BLOQUEO PESIMISTA - ANTI RACE CONDITION)
    -- ========================================================================
    -- ✅ ESTRATEGIA: Bloqueo pesimista con SELECT FOR UPDATE
    -- ✅ ORDEN DETERMINISTA: Ordenar por product_id ASC para evitar deadlocks
    -- ✅ TRANSACCIÓN ATÓMICA: Todo dentro de la misma transacción implícita
    -- ✅ ÚNICA FUENTE DE VERDAD: La tabla inventories es la única que almacena stock
    
    FOR item IN 
        SELECT elem.value 
        FROM jsonb_array_elements(p_items) AS elem
        ORDER BY (elem.value->>'product_id') ASC  -- 🔒 CRÍTICO: Orden determinista para evitar Deadlocks
    LOOP
        v_product_id := (item->>'product_id')::UUID;
        v_qty := COALESCE((item->>'qty')::NUMERIC, 0);
        
        -- ✅ VALIDACIÓN PREVIA: Validar product_id y qty antes de procesar
        IF v_product_id IS NULL THEN
            RAISE EXCEPTION 'Item inválido detectado: product_id es NULL o inválido. Verifica que todos los items del carrito tienen un product_id válido.';
        END IF;
        
        IF v_qty <= 0 THEN
            RAISE EXCEPTION 'Item inválido detectado: La cantidad debe ser mayor a 0 para el producto %', v_product_id;
        END IF;

        -- ✅ PASO A: OBTENER DATOS DEL PRODUCTO (sin bloqueo, solo lectura)
        SELECT name, sku, sale_price_usd 
        INTO v_product_name_db, v_product_sku_db, v_sale_price_usd
        FROM products 
        WHERE id = v_product_id AND company_id = p_company_id;

        -- ✅ VALIDACIÓN: Si no encuentra el producto, lanzar error claro
        IF NOT FOUND THEN
            RAISE EXCEPTION 'Producto no encontrado (ID: %). Verifica que el producto existe y pertenece a la compañía.', v_product_id;
        END IF;

        v_product_name := COALESCE(v_product_name_db, item->>'product_name', 'Producto Sin Nombre');
        v_product_sku := COALESCE(v_product_sku_db, item->>'product_sku', 'N/A');
        v_price := COALESCE(v_sale_price_usd, (item->>'price_usd')::NUMERIC, 0);

        -- ✅ PASO B: BLOQUEO PESIMISTA DE FILA (🔒 EL CANDADO - Serialización de ventas concurrentes)
        -- Si no existe inventario, crear uno con stock 0 primero (sin bloqueo)
        VALUES (p_company_id, p_store_id, v_product_id, 0, 0)
        ON CONFLICT (company_id, store_id, product_id) DO NOTHING;

        -- 🔒 BLOQUEO DE FILA: SELECT FOR UPDATE (Serializa transacciones concurrentes)
        SELECT i.qty INTO v_current_stock
        FROM inventories i
        WHERE i.product_id = v_product_id
          AND i.company_id = p_company_id
          AND i.store_id = p_store_id
        FOR UPDATE OF i;  -- 🔒 BLOQUEO ATÓMICO: Esta fila queda bloqueada hasta COMMIT/ROLLBACK

        -- ✅ VALIDACIÓN POST-BLOQUEO: Verificar que existe inventario
        IF v_current_stock IS NULL THEN
            RAISE EXCEPTION 'Error crítico: No se pudo obtener el stock del producto % (SKU: %) después de crear el registro de inventario.', 
                v_product_name, v_product_sku;
        END IF;

        -- ✅ PASO C: VALIDACIÓN ATÓMICA DE STOCK (Dentro del bloqueo)
        IF v_current_stock < v_qty THEN
            RAISE EXCEPTION 'Stock insuficiente para el producto % (SKU: %) en la sucursal seleccionada. Stock disponible: %, solicitado: %.', 
                v_product_name, v_product_sku, v_current_stock, v_qty;
        END IF;

        -- ✅ PASO D: ACTUALIZACIÓN ATÓMICA DE INVENTARIO (Fila ya está bloqueada)
        UPDATE inventories
        SET 
            qty = qty - v_qty,
            updated_at = NOW()
        WHERE product_id = v_product_id
          AND company_id = p_company_id
          AND store_id = p_store_id;

        -- ✅ PASO E: REGISTRO DE ITEM DE VENTA (Dentro de la misma transacción)
        -- ✅ INCLUIR IMEI: Extraer IMEI del JSON del item si existe
            sale_id, product_id, product_name, product_sku, qty, price_usd, subtotal_usd, imei
        ) VALUES (
            new_sale_id, v_product_id, v_product_name, v_product_sku,
            v_qty, v_price, (v_qty * v_price),
            CASE 
                WHEN (item->>'imei') IS NULL OR (item->>'imei') = '' OR (item->>'imei') = 'null' THEN NULL
                ELSE (item->>'imei')
            END
        );
        
        -- ✅ PASO F: REGISTRO DE MOVIMIENTO DE INVENTARIO (AUDITORÍA - NO CRÍTICO)
        BEGIN
            IF EXISTS (SELECT 1 FROM information_schema.tables 
                      WHERE table_schema = 'public' 
                      AND table_name = 'inventory_movements') THEN
                -- Obtener nombre de la sucursal
                SELECT name INTO v_store_name_mov
                FROM public.stores
                WHERE id = p_store_id AND company_id = p_company_id
                LIMIT 1;
                
                -- Construir mensaje mejorado con información completa
                    product_id, type, qty, store_from_id, store_to_id, reason,
                    user_id, company_id, sale_id, created_at
                ) VALUES (
                    v_product_id, 'OUT', -v_qty, p_store_id, NULL,
                    'Venta - Factura: ' || COALESCE(v_invoice_number, new_sale_id::text) || 
                    ' - Cliente: ' || COALESCE(p_customer_name, 'Cliente General') ||
                    ' - Sucursal: ' || COALESCE(v_store_name_mov, 'Desconocida') ||
                    ' - Producto: ' || COALESCE(v_product_name, 'N/A') ||
                    CASE WHEN v_product_sku IS NOT NULL THEN ' (' || v_product_sku || ')' ELSE '' END,
                    p_cashier_id, p_company_id, new_sale_id, NOW()
                );
            END IF;
        EXCEPTION
            WHEN OTHERS THEN
                -- Log error pero continuar (NO CRÍTICO - la venta ya se procesó correctamente)
                RAISE WARNING 'Error al registrar movimiento de inventario para producto % (SKU: %): %', 
                    v_product_name, v_product_sku, SQLERRM;
        END;
    END LOOP;

    -- 7. REGISTRAR PAGOS
    IF p_is_mixed_payment AND p_mixed_payments IS NOT NULL AND jsonb_array_length(p_mixed_payments) > 0 THEN
        FOR item IN SELECT * FROM jsonb_array_elements(p_mixed_payments) LOOP
                sale_id, company_id, payment_method, amount, amount_usd, amount_bs
            ) VALUES (
                new_sale_id,
                p_company_id,
                COALESCE(item->>'payment_method', 'cash_usd'),
                COALESCE((item->>'amount_usd')::NUMERIC, 0),
                COALESCE((item->>'amount_usd')::NUMERIC, 0),
                COALESCE((item->>'amount_bs')::NUMERIC, 0)
            );
        END LOOP;
    ELSE
            sale_id, company_id, payment_method, amount, amount_usd, amount_bs
        ) VALUES (
            new_sale_id,
            p_company_id,
            p_payment_method,
            v_total_calculado,
            v_total_calculado,
            v_total_bs_final
        );
    END IF;

    -- 8. MANEJAR FINANCIAMIENTO KRECE
    IF p_krece_enabled THEN
            company_id, sale_id, customer_id, amount_financed, remaining_amount, status
        ) VALUES (
            p_company_id, new_sale_id, p_customer_id,
            COALESCE(p_krece_financed_amount_usd, 0), 
            COALESCE(p_krece_financed_amount_usd, 0), 
            'active'
        );
    END IF;

    -- 9. RETORNAR RESULTADO
    RETURN jsonb_build_object(
        'success', true, 
        'sale_id', new_sale_id, 
        'id', new_sale_id, 
        'data', new_sale_id,
        'invoice_number', v_invoice_number,
        'subtotal', v_subtotal_calculado,
        'total', v_total_calculado,
        'total_bs', v_total_bs_final
    );
    
EXCEPTION 
    WHEN OTHERS THEN
        RAISE EXCEPTION 'Error al procesar la venta: % (Company: %, Store: %, Cashier: %)', 
            SQLERRM, p_company_id, p_store_id, p_cashier_id;
END;
$$;


--
-- Name: FUNCTION process_sale(p_company_id uuid, p_store_id uuid, p_cashier_id uuid, p_customer_id uuid, p_payment_method text, p_customer_name text, p_bcv_rate numeric, p_customer_id_number text, p_items jsonb, p_notes text, p_tax_rate numeric, p_krece_enabled boolean, p_krece_initial_amount_usd numeric, p_krece_financed_amount_usd numeric, p_krece_initial_percentage numeric, p_is_mixed_payment boolean, p_mixed_payments jsonb, p_subtotal_usd numeric, p_total_bs numeric, p_krece_initial_amount_bs numeric, p_krece_financed_amount_bs numeric, p_cashea_enabled boolean, p_cashea_initial_amount_usd numeric, p_cashea_financed_amount_usd numeric, p_cashea_initial_percentage numeric, p_cashea_initial_amount_bs numeric, p_cashea_financed_amount_bs numeric); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.process_sale(p_company_id uuid, p_store_id uuid, p_cashier_id uuid, p_customer_id uuid, p_payment_method text, p_customer_name text, p_bcv_rate numeric, p_customer_id_number text, p_items jsonb, p_notes text, p_tax_rate numeric, p_krece_enabled boolean, p_krece_initial_amount_usd numeric, p_krece_financed_amount_usd numeric, p_krece_initial_percentage numeric, p_is_mixed_payment boolean, p_mixed_payments jsonb, p_subtotal_usd numeric, p_total_bs numeric, p_krece_initial_amount_bs numeric, p_krece_financed_amount_bs numeric, p_cashea_enabled boolean, p_cashea_initial_amount_usd numeric, p_cashea_financed_amount_usd numeric, p_cashea_initial_percentage numeric, p_cashea_initial_amount_bs numeric, p_cashea_financed_amount_bs numeric) IS 'Función blindada para procesar ventas con BLOQUEO PESIMISTA (Pessimistic Locking).
Implementa SELECT FOR UPDATE para serializar transacciones concurrentes y eliminar race conditions.
Orden determinista de items (product_id ASC) previene deadlocks.
Validación atómica de stock dentro del bloqueo garantiza integridad de datos.
Única fuente de verdad: La tabla inventories es la única que almacena stock (sistema normalizado).
Timeout de bloqueo (4000ms) previene transacciones zombie que bloqueen la tienda.
Todas las operaciones (UPDATE inventario, INSERT sale_items, INSERT movimientos) ocurren dentro de la misma transacción atómica.
Elimina completamente el problema de Split-Brain causado por race conditions en lecturas concurrentes de inventories.';


--
-- Name: restore_product(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.restore_product(p_product_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_user_company_id UUID;
  v_product_company_id UUID;
  v_product_name TEXT;
  v_product_active BOOLEAN;
  v_user_id UUID;
  v_rows_affected INTEGER;
BEGIN
  -- ====================================================================================
  -- VALIDACIÓN DE SEGURIDAD CRÍTICA: Solo master_admin puede restaurar
  -- ====================================================================================
  IF NOT public.is_master_admin() THEN
    RAISE EXCEPTION 'Acceso denegado. Función exclusiva de Laboratorio/Técnico. Solo usuarios con rol master_admin pueden restaurar productos eliminados.';
  END IF;

  -- Obtener información del usuario actual (opcional, solo para logging)
  SELECT company_id, id INTO v_user_company_id, v_user_id
  FROM public.users
  WHERE auth_user_id = auth.uid()
  LIMIT 1;

  -- ====================================================================================
  -- BÚSQUEDA FORENSE: Buscar producto SIN filtrar por active NI company_id
  -- ====================================================================================
  -- IMPORTANTE: 
  -- - master_admin puede restaurar productos de CUALQUIER compañía
  -- - Buscamos solo por id, sin restricción de company_id
  -- - NO filtramos por active para encontrar productos inactivos
  -- ====================================================================================
  SELECT name, active, company_id 
  INTO v_product_name, v_product_active, v_product_company_id
  FROM public.products
  WHERE id = p_product_id;
  -- ⚠️ CRÍTICO: NO filtramos por company_id ni active aquí
  -- master_admin puede restaurar productos de cualquier compañía

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'success', false,
      'message', 'Producto no encontrado.'
    );
  END IF;

  -- ====================================================================================
  -- VALIDACIÓN: Verificar que el producto esté inactivo
  -- ====================================================================================
  IF v_product_active = true THEN
    RETURN jsonb_build_object(
      'success', false,
      'message', 'El producto "' || v_product_name || '" ya está activo. No es necesario restaurarlo.'
    );
  END IF;

  -- ====================================================================================
  -- RESTAURACIÓN: SOLO actualizar products.active
  -- ====================================================================================
  -- PRINCIPIO DE NO-INTERVENCIÓN DE STOCK (Crítico):
  -- - Esta función SOLO tiene permiso para hacer UPDATE en la tabla products
  -- - PROHIBIDO tocar la tabla inventories
  -- - Racional: Al volver a poner active = true, las vistas y reportes volverán a
  --   "ver" y sumar automáticamente las cantidades que ya existen en inventories
  --   para cada sucursal. No hay que sumar, restar ni resetear nada.
  -- ====================================================================================
  -- Restores product visibility. Does NOT modify inventory counts to preserve historical data.
  -- ====================================================================================
  -- master_admin puede restaurar productos de CUALQUIER compañía
  -- NO filtramos por company_id en el UPDATE
  UPDATE public.products
  SET active = true,
      updated_at = NOW()
  WHERE id = p_product_id 
    AND active = false  -- Solo actualizar si está inactivo (seguridad adicional)
  RETURNING 1 INTO v_rows_affected;

  IF v_rows_affected = 0 THEN
    RETURN jsonb_build_object(
      'success', false,
      'message', 'No se pudo restaurar el producto. Puede que ya esté activo o haya sido modificado.'
    );
  END IF;

  -- Retornar éxito con confirmación de preservación de inventario
  RETURN jsonb_build_object(
    'success', true,
    'message', 'Producto "' || v_product_name || '" restaurado exitosamente. El inventario histórico se ha preservado intacto.',
    'product_id', p_product_id,
    'product_name', v_product_name,
    'product_company_id', v_product_company_id,
    'previous_status', 'inactive',
    'new_status', 'active',
    'inventory_preserved', true,
    'note', 'Restores product visibility. Does NOT modify inventory counts to preserve historical data.'
  );

EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object(
    'success', false,
    'message', 'Error al restaurar producto: ' || SQLERRM
  );
END;
$$;


--
-- Name: FUNCTION restore_product(p_product_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.restore_product(p_product_id uuid) IS 'Restaura un producto eliminado (soft delete) cambiando active de false a true.
SEGURIDAD: Solo usuarios con rol master_admin pueden ejecutar esta función.
PRESERVACIÓN DE DATOS HISTÓRICOS: Esta función SOLO actualiza products.active.
NO modifica la tabla inventories. El inventario histórico se preserva automáticamente.
Restores product visibility. Does NOT modify inventory counts to preserve historical data.
master_admin puede restaurar productos de CUALQUIER compañía sin restricción de company_id.';


--
-- Name: sync_web_product_price(uuid, numeric, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_web_product_price(p_product_id uuid, p_sale_price_usd numeric, p_web_image_url text DEFAULT NULL::text, p_web_visible boolean DEFAULT NULL::boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_company_id UUID;
  v_user_id UUID;
  v_current_price NUMERIC(15,4);
  v_product_name TEXT;
  v_normalized_image_url TEXT;
  v_final_image_url TEXT;
  v_final_visible BOOLEAN;
  v_old_image_url TEXT;
BEGIN
  -- 1. Validar autenticación y obtener company_id
  SELECT company_id, id INTO v_company_id, v_user_id
  FROM public.users
  WHERE auth_user_id = auth.uid()
  LIMIT 1;

  IF v_company_id IS NULL OR v_user_id IS NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Usuario no autenticado o sin company_id'
    );
  END IF;

  -- 2. Validar que el usuario es admin
  IF NOT public.is_admin() THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Solo los administradores pueden sincronizar productos web'
    );
  END IF;

  -- 3. Validar que el producto existe y pertenece a la company
  SELECT sale_price_usd, name INTO v_current_price, v_product_name
  FROM public.products
  WHERE id = p_product_id
    AND company_id = v_company_id
    AND active = true;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Producto no encontrado o inactivo'
    );
  END IF;

  -- 4. VALIDACIONES DE NEGOCIO
  -- Precio debe ser positivo
  IF p_sale_price_usd <= 0 THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'El precio de venta debe ser mayor a 0'
    );
  END IF;

  -- ✅ REGLA: Si no hay image_url, forzar visible = false (PERMITIR actualizar precio)
  IF p_web_image_url IS NULL OR p_web_image_url = '' THEN
    p_web_visible := false;
  END IF;

  -- ✅ REGLA: Si visible = true después de forzar, debe haber image_url
  IF p_web_visible = true AND (p_web_image_url IS NULL OR p_web_image_url = '') THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Un producto visible debe tener una URL de imagen'
    );
  END IF;

  -- 5. ACTUALIZAR PRECIO EN products (ATÓMICO)
  UPDATE public.products
  SET 
    sale_price_usd = p_sale_price_usd,
    updated_at = NOW()
  WHERE id = p_product_id
    AND company_id = v_company_id;

  -- 6. ACTUALIZAR/CREAR METADATOS WEB (MECANISMO ROBUSTO)
  -- ✅ PASO 1: Normalizar la URL: NULL si está vacía o solo espacios
  v_normalized_image_url := NULLIF(TRIM(COALESCE(p_web_image_url, '')), '');
  
  -- ✅ PASO 2: Obtener imagen anterior (si existe) para verificación
  SELECT image_url INTO v_old_image_url
  FROM public.web_product_metadata
  WHERE product_id = p_product_id;
  
  -- ✅ PASO 3: MECANISMO EXPLÍCITO - Determinar qué imagen usar
  -- Si se proporcionó URL → usar la proporcionada
  -- Si NO se proporcionó URL (NULL) → usar la existente (si hay) o NULL (si no hay)
  IF v_normalized_image_url IS NOT NULL THEN
    -- ✅ CASO 1: Se proporcionó una URL de imagen (nueva o la misma para mantener)
    v_final_image_url := v_normalized_image_url;
  ELSE
    -- ✅ CASO 2: NO se proporcionó URL (NULL) - Usar la imagen existente si hay
    -- Esto se usa cuando solo queremos cambiar la visibilidad sin cambiar la imagen
    v_final_image_url := v_old_image_url;  -- ✅ Mantener imagen existente o NULL si no hay
  END IF;
  
  -- ✅ PASO 4: ACTUALIZAR o CREAR registro
    product_id, image_url, visible, updated_at
  ) VALUES (
    p_product_id, 
    v_final_image_url,  -- ✅ Imagen final (proporcionada o existente)
    COALESCE(p_web_visible, false),
    NOW()
  )
  ON CONFLICT (product_id)
  DO UPDATE SET
    image_url = EXCLUDED.image_url,  -- ✅ Actualizar imagen (proporcionada o mantener existente)
    visible = COALESCE(EXCLUDED.visible, false),  -- ✅ Actualizar visibilidad
    updated_at = NOW();

  -- 7. Obtener el valor final guardado de image_url para confirmación
  SELECT image_url, visible INTO v_final_image_url, v_final_visible
  FROM public.web_product_metadata
  WHERE product_id = p_product_id;

  -- 8. Retornar éxito con información completa
  RETURN jsonb_build_object(
    'success', true,
    'message', 'Producto sincronizado exitosamente',
    'product_id', p_product_id,
    'previous_price', v_current_price,
    'new_price', p_sale_price_usd,
    'product_name', v_product_name,
    'image_url_sent', v_normalized_image_url,
    'image_url_old', v_old_image_url,  -- ✅ Imagen anterior (para verificación)
    'image_url_final', v_final_image_url,  -- ✅ Imagen final guardada
    'visible_saved', COALESCE(p_web_visible, false),
    'visible_final', v_final_visible
  );

EXCEPTION
  WHEN OTHERS THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Error al sincronizar producto: ' || SQLERRM
    );
END;
$$;


--
-- Name: FUNCTION sync_web_product_price(p_product_id uuid, p_sale_price_usd numeric, p_web_image_url text, p_web_visible boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.sync_web_product_price(p_product_id uuid, p_sale_price_usd numeric, p_web_image_url text, p_web_visible boolean) IS 'Sincroniza precio y metadatos de producto para catálogo web. 
Valida reglas de negocio y registra cambios. Solo para productos activos.
Actualiza atomicamente products y web_product_metadata.
REGLAS: visible = true requiere image_url. Si no hay image_url, visible = false.';


--
-- Name: transfer_inventory(uuid, uuid, uuid, integer, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transfer_inventory(p_product_id uuid, p_from_store_id uuid, p_to_store_id uuid, p_quantity integer, p_company_id uuid, p_transferred_by uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_from_inventory_id uuid;
  v_to_inventory_id uuid;
  v_from_qty integer;
  v_to_qty integer;
  v_transfer_id uuid;
  v_product_name text;
  v_from_store_name text;
  v_to_store_name text;
  v_user_role text;
  v_new_from_qty integer;
  v_new_to_qty integer;
BEGIN
  -- Verificar permisos del usuario (solo admin)
  SELECT role INTO v_user_role
  FROM public.users
  WHERE auth_user_id = auth.uid() 
    AND company_id = p_company_id;

  IF v_user_role IS NULL THEN
    RAISE EXCEPTION 'Usuario no encontrado o sin permisos';
  END IF;

  IF v_user_role != 'admin' THEN
    RAISE EXCEPTION 'Solo los administradores pueden transferir inventario entre sucursales';
  END IF;

  -- Validar cantidad
  IF p_quantity <= 0 THEN
    RAISE EXCEPTION 'La cantidad debe ser mayor a 0';
  END IF;

  -- Obtener nombre del producto
  SELECT name INTO v_product_name
  FROM public.products
  WHERE id = p_product_id AND company_id = p_company_id;

  IF v_product_name IS NULL THEN
    RAISE EXCEPTION 'Producto no encontrado';
  END IF;

  -- Obtener nombres de las tiendas
  SELECT name INTO v_from_store_name
  FROM public.stores
  WHERE id = p_from_store_id AND company_id = p_company_id;

  SELECT name INTO v_to_store_name
  FROM public.stores
  WHERE id = p_to_store_id AND company_id = p_company_id;

  IF v_from_store_name IS NULL OR v_to_store_name IS NULL THEN
    RAISE EXCEPTION 'Una o ambas tiendas no fueron encontradas';
  END IF;

  -- Verificar que las tiendas sean diferentes
  IF p_from_store_id = p_to_store_id THEN
    RAISE EXCEPTION 'No puedes transferir a la misma tienda';
  END IF;

  -- ====================================================================================
  -- BLOQUEO DE CONCURRENCIA: SELECT ... FOR UPDATE
  -- ====================================================================================
  -- Esto congela el stock de origen y evita que un cajero venda mientras se transfiere
  SELECT id, qty INTO v_from_inventory_id, v_from_qty
  FROM public.inventories
  WHERE product_id = p_product_id 
    AND store_id = p_from_store_id 
    AND company_id = p_company_id
  FOR UPDATE;  -- ← BLOQUEO DE FILA: Congela el stock hasta COMMIT

  IF v_from_inventory_id IS NULL THEN
    RAISE EXCEPTION 'No hay inventario del producto en la tienda de origen';
  END IF;

  -- Verificar que haya suficiente cantidad
  IF v_from_qty < p_quantity THEN
    RAISE EXCEPTION 'No hay suficiente stock. Disponible: %, Solicitado: %', v_from_qty, p_quantity;
  END IF;

  -- Obtener o crear inventario de destino
  SELECT id, qty INTO v_to_inventory_id, v_to_qty
  FROM public.inventories
  WHERE product_id = p_product_id 
    AND store_id = p_to_store_id 
    AND company_id = p_company_id;

  -- Si el inventario de destino no existe, crearlo
  IF v_to_inventory_id IS NULL THEN
      product_id,
      store_id,
      company_id,
      qty,
      min_qty
    ) VALUES (
      p_product_id,
      p_to_store_id,
      p_company_id,
      0,
      5
    ) RETURNING id INTO v_to_inventory_id;
    v_to_qty := 0;
  END IF;

  -- ====================================================================================
  -- VALIDACIÓN ATÓMICA: UPDATE con validación en WHERE
  -- ====================================================================================
  -- Si el stock cambió entre el SELECT y el UPDATE, el WHERE falla y lanza error
  UPDATE public.inventories
  SET qty = qty - p_quantity,
      updated_at = NOW()
  WHERE id = v_from_inventory_id
    AND qty >= p_quantity  -- ← VALIDACIÓN ATÓMICA: Si stock cambió, no encuentra fila
  RETURNING qty INTO v_new_from_qty;

  IF NOT FOUND THEN
    -- Stock cambió durante la transacción (race condition detectada)
    RAISE EXCEPTION 'Stock insuficiente. El stock cambió durante la transferencia. Intenta nuevamente.';
  END IF;

  -- Actualizar inventario de destino (sumar)
  UPDATE public.inventories
  SET qty = qty + p_quantity,
      updated_at = NOW()
  WHERE id = v_to_inventory_id
  RETURNING qty INTO v_new_to_qty;

  -- Crear registro de transferencia
    product_id,
    from_store_id,
    to_store_id,
    quantity,
    company_id,
    transferred_by,
    status
  ) VALUES (
    p_product_id,
    p_from_store_id,
    p_to_store_id,
    p_quantity,
    p_company_id,
    p_transferred_by,
    'completed'
  ) RETURNING id INTO v_transfer_id;

  -- ====================================================================================
  -- AUDITORÍA: Insertar movimientos de inventario
  -- ====================================================================================
  -- Movimiento de salida desde tienda origen
    product_id,
    type,
    qty,
    store_from_id,
    store_to_id,
    reason,
    user_id,
    company_id
  ) VALUES (
    p_product_id,
    'TRANSFER',
    -p_quantity,
    p_from_store_id,
    p_to_store_id,
    'Transferencia a ' || v_to_store_name,
    p_transferred_by,
    p_company_id
  );

  -- Movimiento de entrada a tienda destino
    product_id,
    type,
    qty,
    store_from_id,
    store_to_id,
    reason,
    user_id,
    company_id
  ) VALUES (
    p_product_id,
    'TRANSFER',
    p_quantity,
    p_from_store_id,
    p_to_store_id,
    'Transferencia desde ' || v_from_store_name,
    p_transferred_by,
    p_company_id
  );

  -- Retornar resultado exitoso
  RETURN json_build_object(
    'error', false,
    'message', 'Transferencia completada exitosamente',
    'transfer_id', v_transfer_id,
    'product_name', v_product_name,
    'from_store', v_from_store_name,
    'to_store', v_to_store_name,
    'quantity', p_quantity,
    'new_from_qty', v_new_from_qty,
    'new_to_qty', v_new_to_qty
  );

  -- NO capturamos excepciones aquí - dejamos que PostgreSQL haga ROLLBACK automático
  -- Si cualquier operación falla, toda la transacción se revierte
END;
$$;


--
-- Name: FUNCTION transfer_inventory(p_product_id uuid, p_from_store_id uuid, p_to_store_id uuid, p_quantity integer, p_company_id uuid, p_transferred_by uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.transfer_inventory(p_product_id uuid, p_from_store_id uuid, p_to_store_id uuid, p_quantity integer, p_company_id uuid, p_transferred_by uuid) IS 'Transfiere productos de inventario entre tiendas. SOLO administradores pueden transferir. Versión blindada con bloqueos de concurrencia y validaciones atómicas.';


--
-- Name: update_product(uuid, text, text, text, text, numeric, numeric, numeric, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_product(p_product_id uuid, p_sku text DEFAULT NULL::text, p_barcode text DEFAULT NULL::text, p_name text DEFAULT NULL::text, p_category text DEFAULT NULL::text, p_cost_usd numeric DEFAULT NULL::numeric, p_sale_price_usd numeric DEFAULT NULL::numeric, p_tax_rate numeric DEFAULT NULL::numeric, p_active boolean DEFAULT NULL::boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_company_id UUID;
    v_user_id UUID;
    v_product_record RECORD;
    v_existing_product_id UUID;
    v_update_fields JSONB := '{}'::jsonb;
BEGIN
    -- 1. Obtener Company ID y User ID del usuario logueado (Seguridad)
    SELECT company_id, id INTO v_company_id, v_user_id
    FROM public.users
    WHERE auth_user_id = auth.uid()
    LIMIT 1;

    IF v_company_id IS NULL OR v_user_id IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Usuario no encontrado o no asociado a una compañía'
        );
    END IF;

    -- 2. Verificar que el usuario es admin
    IF NOT EXISTS (
        SELECT 1 FROM public.users
        WHERE id = v_user_id
        AND role = 'admin'
    ) THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Solo los administradores pueden editar productos'
        );
    END IF;

    -- 3. Verificar que el producto existe y pertenece a la empresa
    SELECT * INTO v_product_record
    FROM public.products
    WHERE id = p_product_id
    AND company_id = v_company_id;

    IF NOT FOUND THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Producto no encontrado o no pertenece a tu empresa'
        );
    END IF;

    -- 4. VALIDACIÓN: Verificar duplicado de SKU (si se está cambiando)
    IF p_sku IS NOT NULL AND p_sku != v_product_record.sku THEN
        SELECT id INTO v_existing_product_id
        FROM public.products
        WHERE company_id = v_company_id
        AND sku = p_sku
        AND id != p_product_id
        AND active = true;

        IF v_existing_product_id IS NOT NULL THEN
            RETURN jsonb_build_object(
                'success', false,
                'error', 'Ya existe otro producto activo con el SKU: ' || p_sku
            );
        END IF;
    END IF;

    -- 5. VALIDACIÓN: Verificar duplicado de Código de Barras (si se está cambiando)
    IF p_barcode IS NOT NULL AND p_barcode != COALESCE(v_product_record.barcode, '') THEN
        -- Solo validar si el barcode no está vacío
        IF p_barcode != '' THEN
            SELECT id INTO v_existing_product_id
            FROM public.products
            WHERE company_id = v_company_id
            AND barcode = p_barcode
            AND id != p_product_id
            AND active = true;

            IF v_existing_product_id IS NOT NULL THEN
                RETURN jsonb_build_object(
                    'success', false,
                    'error', 'Ya existe otro producto activo con el Código de Barras: ' || p_barcode
                );
            END IF;
        END IF;
    END IF;

    -- 6. VALIDACIÓN: Precios y costos deben ser positivos
    IF p_cost_usd IS NOT NULL AND p_cost_usd < 0 THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'El costo no puede ser negativo'
        );
    END IF;

    IF p_sale_price_usd IS NOT NULL AND p_sale_price_usd < 0 THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'El precio de venta no puede ser negativo'
        );
    END IF;

    -- 7. Construir objeto de actualización solo con campos proporcionados
    IF p_sku IS NOT NULL THEN
        v_update_fields := v_update_fields || jsonb_build_object('sku', p_sku);
    END IF;

    IF p_barcode IS NOT NULL THEN
        v_update_fields := v_update_fields || jsonb_build_object('barcode', NULLIF(p_barcode, ''));
    END IF;

    IF p_name IS NOT NULL THEN
        v_update_fields := v_update_fields || jsonb_build_object('name', p_name);
    END IF;

    IF p_category IS NOT NULL THEN
        v_update_fields := v_update_fields || jsonb_build_object('category', NULLIF(p_category, ''));
    END IF;

    IF p_cost_usd IS NOT NULL THEN
        v_update_fields := v_update_fields || jsonb_build_object('cost_usd', p_cost_usd);
    END IF;

    IF p_sale_price_usd IS NOT NULL THEN
        v_update_fields := v_update_fields || jsonb_build_object('sale_price_usd', p_sale_price_usd);
    END IF;

    IF p_tax_rate IS NOT NULL THEN
        v_update_fields := v_update_fields || jsonb_build_object('tax_rate', p_tax_rate);
    END IF;

    IF p_active IS NOT NULL THEN
        v_update_fields := v_update_fields || jsonb_build_object('active', p_active);
    END IF;

    -- Agregar updated_at siempre
    v_update_fields := v_update_fields || jsonb_build_object('updated_at', NOW());

    -- 8. Ejecutar UPDATE dinámico
    -- Nota: PostgreSQL no permite UPDATE dinámico directo, así que usamos CASE
    UPDATE public.products
    SET
        sku = COALESCE(p_sku, sku),
        barcode = CASE WHEN p_barcode IS NOT NULL THEN NULLIF(p_barcode, '') ELSE barcode END,
        name = COALESCE(p_name, name),
        category = CASE WHEN p_category IS NOT NULL THEN NULLIF(p_category, '') ELSE category END,
        cost_usd = COALESCE(p_cost_usd, cost_usd),
        sale_price_usd = COALESCE(p_sale_price_usd, sale_price_usd),
        tax_rate = COALESCE(p_tax_rate, tax_rate),
        active = COALESCE(p_active, active),
        updated_at = NOW()
    WHERE id = p_product_id
    AND company_id = v_company_id;

    -- 9. Retornar resultado exitoso
    RETURN jsonb_build_object(
        'success', true,
        'message', 'Producto actualizado exitosamente',
        'product_id', p_product_id,
        'updated_fields', v_update_fields
    );

EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object(
        'success', false,
        'error', 'Error al actualizar el producto: ' || SQLERRM
    );
END;
$$;


--
-- Name: FUNCTION update_product(p_product_id uuid, p_sku text, p_barcode text, p_name text, p_category text, p_cost_usd numeric, p_sale_price_usd numeric, p_tax_rate numeric, p_active boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.update_product(p_product_id uuid, p_sku text, p_barcode text, p_name text, p_category text, p_cost_usd numeric, p_sale_price_usd numeric, p_tax_rate numeric, p_active boolean) IS 'Actualiza un producto existente. Permite modificar: SKU, Código de Barras, Nombre, Categoría, Costo, Precio de Venta, Tasa de Impuesto, y Estado (active).
NO permite modificar el stock (se hace mediante Transferencias o Ajustes de Inventario).
Valida que no se dupliquen SKU o Código de Barras con otros productos activos.
Solo administradores pueden ejecutar esta función.';


--
-- Name: update_store_inventory(uuid, uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_store_inventory(p_product_id uuid, p_store_id uuid, p_qty integer, p_min_qty integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  user_company_id uuid;
  user_id_val uuid;
  user_name_val text;
  store_name_val text;
  product_name_val text;
  product_sku_val text;
  old_qty integer;
  new_qty integer;
  qty_difference integer;
  movement_reason text;
  inventory_record record;
BEGIN
  -- Get user's company and user info
  SELECT 
    u.company_id,
    u.id,
    COALESCE(u.name, u.email, 'Admin')
  INTO 
    user_company_id,
    user_id_val,
    user_name_val
  FROM public.users u
  WHERE u.auth_user_id = auth.uid()
  LIMIT 1;

  IF user_company_id IS NULL THEN
    RETURN json_build_object(
      'error', true,
      'message', 'User not found',
      'code', 'USER_NOT_FOUND'
    );
  END IF;

  -- SOLO ADMINS pueden actualizar stock manualmente
  -- Managers NO pueden editar stock (solo pueden ver y vender)
  IF NOT public.is_admin() THEN
    RETURN json_build_object(
      'error', true,
      'message', 'Solo los administradores pueden actualizar el stock manualmente. Los gerentes solo pueden ver el inventario y procesar ventas.',
      'code', 'INSUFFICIENT_PERMISSIONS'
    );
  END IF;

  -- Obtener información del producto y tienda
  SELECT 
    p.name,
    p.sku,
    s.name
  INTO 
    product_name_val,
    product_sku_val,
    store_name_val
  FROM public.products p
  JOIN public.stores s ON s.company_id = user_company_id
  WHERE p.id = p_product_id
    AND s.id = p_store_id
    AND p.company_id = user_company_id
  LIMIT 1;

  -- Obtener stock anterior (si existe)
  SELECT COALESCE(qty, 0) INTO old_qty
  FROM public.inventories
  WHERE company_id = user_company_id
    AND store_id = p_store_id
    AND product_id = p_product_id;

  -- Si no existe, el stock anterior es 0
  IF old_qty IS NULL THEN
    old_qty := 0;
  END IF;

  -- El nuevo stock es el valor pasado como parámetro
  new_qty := p_qty;

  -- Calcular la diferencia
  qty_difference := new_qty - old_qty;

  -- Update or insert inventory
  VALUES (
    user_company_id, 
    p_store_id, 
    p_product_id, 
    p_qty, 
    COALESCE(p_min_qty, 5)
  )
  ON CONFLICT (company_id, store_id, product_id)
  DO UPDATE SET 
    qty = EXCLUDED.qty,
    min_qty = COALESCE(EXCLUDED.min_qty, inventories.min_qty),
    updated_at = now()
  RETURNING * INTO inventory_record;

  -- ✅ Registrar movimiento de inventario para auditoría (solo si hay diferencia)
  IF qty_difference != 0 THEN
    BEGIN
      -- Construir mensaje según si es aumento o disminución
      IF qty_difference > 0 THEN
        movement_reason := format(
          'Aumento manual de stock (%s unidades) en %s',
          qty_difference,
          COALESCE(store_name_val, 'sucursal')
        );
      ELSE
        movement_reason := format(
          'Disminución manual de stock (%s unidades) en %s',
          ABS(qty_difference),
          COALESCE(store_name_val, 'sucursal')
        );
      END IF;

      -- Verificar que la tabla inventory_movements existe antes de insertar
      IF EXISTS (SELECT 1 FROM information_schema.tables 
                WHERE table_schema = 'public' 
                AND table_name = 'inventory_movements') THEN
          company_id,
          type,
          product_id,
          qty,
          store_from_id,
          store_to_id,
          reason,
          user_id,
          created_at
        ) VALUES (
          user_company_id,
          'ADJUST',
          p_product_id,
          qty_difference::numeric, -- Cast a numeric para compatibilidad con la tabla
          p_store_id,
          NULL,
          movement_reason || ' - Producto: ' || COALESCE(product_name_val, 'N/A') || 
          CASE 
            WHEN product_sku_val IS NOT NULL THEN ' (' || product_sku_val || ')'
            ELSE ''
          END || ' - Admin: ' || COALESCE(user_name_val, 'Admin'),
          user_id_val,
          NOW()
        );
      END IF;
    EXCEPTION
      WHEN OTHERS THEN
        -- Si falla la inserción de movimiento, continuar (NO CRÍTICO)
        -- La actualización de stock ya se hizo correctamente, esto es solo para auditoría
        NULL;
    END;
  END IF;

  RETURN row_to_json(inventory_record);
EXCEPTION
  WHEN OTHERS THEN
    RETURN json_build_object(
      'error', true,
      'message', SQLERRM,
      'code', SQLSTATE
    );
END;
$$;


--
-- Name: FUNCTION update_store_inventory(p_product_id uuid, p_store_id uuid, p_qty integer, p_min_qty integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.update_store_inventory(p_product_id uuid, p_store_id uuid, p_qty integer, p_min_qty integer) IS 'Actualiza el stock de un producto en una tienda específica. Solo los administradores pueden usar esta función. 
Registra automáticamente los cambios en inventory_movements con tipo ADJUST para auditoría forense.
Incluye información detallada: aumento/disminución, cantidad, sucursal, producto, y usuario que realizó el cambio.';


