--
-- Name: dashboard_stats_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.dashboard_stats_view AS
 WITH product_stats AS (
         SELECT p.company_id,
            count(DISTINCT p.id) AS total_products
           FROM public.products p
          WHERE (p.active = true)
          GROUP BY p.company_id
        ), inventory_stats AS (
         SELECT i.company_id,
            COALESCE(sum(i.qty), (0)::numeric) AS total_stock,
            COALESCE(sum((i.qty * COALESCE(p.sale_price_usd, (0)::numeric))), (0)::numeric) AS total_value
           FROM (public.inventories i
             JOIN public.products p ON ((i.product_id = p.id)))
          WHERE (p.active = true)
          GROUP BY i.company_id
        ), low_stock_stats AS (
         SELECT i.company_id,
            count(DISTINCT
                CASE
                    WHEN ((i.qty > (0)::numeric) AND (i.qty <= (10)::numeric)) THEN i.product_id
                    ELSE NULL::uuid
                END) AS low_stock_count
           FROM (public.inventories i
             JOIN public.products p ON ((i.product_id = p.id)))
          WHERE (p.active = true)
          GROUP BY i.company_id
        )
 SELECT COALESCE(ps.company_id, ins.company_id, lss.company_id) AS company_id,
    COALESCE(ps.total_products, (0)::bigint) AS total_products,
    COALESCE(ins.total_stock, (0)::numeric) AS total_stock,
    COALESCE(ins.total_value, (0)::numeric) AS total_value,
    COALESCE(lss.low_stock_count, (0)::bigint) AS low_stock_count
   FROM ((product_stats ps
     FULL JOIN inventory_stats ins ON ((ps.company_id = ins.company_id)))
     FULL JOIN low_stock_stats lss ON ((COALESCE(ps.company_id, ins.company_id) = lss.company_id)));


