--
-- Name: inventory_statistics_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.inventory_statistics_view AS
 SELECT i.store_id,
    i.company_id,
    count(DISTINCT i.product_id) FILTER (WHERE (p.active = true)) AS total_products,
    sum(i.qty) FILTER (WHERE (p.active = true)) AS total_stock,
    sum((i.qty * COALESCE(p.sale_price_usd, (0)::numeric))) FILTER (WHERE (p.active = true)) AS total_value,
    count(DISTINCT i.product_id) FILTER (WHERE ((p.active = true) AND (i.qty <= i.min_qty) AND (i.qty > (0)::numeric))) AS low_stock_count,
    count(DISTINCT i.product_id) FILTER (WHERE ((p.active = true) AND (i.qty = (0)::numeric))) AS out_of_stock_count
   FROM (public.inventories i
     JOIN public.products p ON ((i.product_id = p.id)))
  WHERE (p.active = true)
  GROUP BY i.store_id, i.company_id;


