--
-- Name: sales_history_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.sales_history_view AS
 SELECT s.id,
    s.invoice_number,
    s.customer_id,
    s.store_id,
    s.cashier_id,
    s.company_id,
    s.subtotal_usd,
    s.tax_amount_usd,
    s.total_usd,
    s.total_bs,
    s.bcv_rate_used,
    s.payment_method,
    s.is_mixed_payment,
    s.krece_enabled,
    s.krece_initial_amount_usd,
    s.krece_financed_amount_usd,
    s.krece_initial_percentage,
    s.notes,
    s.created_at,
    s.updated_at,
        CASE
            WHEN ((s.krece_enabled = true) AND (s.notes ~~ '%financing_type:cashea%'::text)) THEN 'CASHEA'::text
            WHEN ((s.krece_enabled = true) AND (s.notes ~~ '%financing_type:krece%'::text)) THEN 'KRECE'::text
            WHEN (s.krece_enabled = true) THEN 'KRECE'::text
            ELSE 'CONTADO'::text
        END AS financing_type,
        CASE
            WHEN ((s.krece_enabled = true) AND (s.notes ~~ '%financing_type:cashea%'::text)) THEN 'CASHEA'::text
            WHEN ((s.krece_enabled = true) AND (s.notes ~~ '%financing_type:krece%'::text)) THEN 'KRECE'::text
            WHEN (s.krece_enabled = true) THEN 'KRECE'::text
            ELSE 'DE CONTADO'::text
        END AS financing_label,
        CASE
            WHEN (s.is_mixed_payment = true) THEN 'Mixto'::character varying
            WHEN ((s.payment_method)::text = 'cash_usd'::text) THEN 'Efectivo USD'::character varying
            WHEN ((s.payment_method)::text = 'cash_bs'::text) THEN 'Efectivo BS'::character varying
            WHEN ((s.payment_method)::text = 'card'::text) THEN 'Tarjeta'::character varying
            WHEN ((s.payment_method)::text = 'transfer'::text) THEN 'Transferencia'::character varying
            WHEN ((s.payment_method)::text = 'binance'::text) THEN 'Binance'::character varying
            WHEN ((s.payment_method)::text = 'zelle'::text) THEN 'Zelle'::character varying
            WHEN ((s.payment_method)::text = 'pago_movil'::text) THEN 'Pago Móvil'::character varying
            WHEN ((s.payment_method)::text = 'pos'::text) THEN 'Punto de Venta'::character varying
            ELSE COALESCE(s.payment_method, 'Desconocido'::character varying)
        END AS payment_method_label,
    COALESCE(st.name, 'Tienda N/A'::text) AS store_name,
    COALESCE(u.name, u.email, 'Cajero N/A'::text) AS cashier_name,
    COALESCE(s.customer_name, c.name, 'Sin Cliente'::text) AS customer_name,
    COALESCE(s.customer_id_number, c.id_number, ''::text) AS customer_id_number
   FROM (((public.sales s
     LEFT JOIN public.stores st ON ((s.store_id = st.id)))
     LEFT JOIN public.users u ON ((s.cashier_id = u.id)))
     LEFT JOIN public.customers c ON ((s.customer_id = c.id)));


--
-- Name: VIEW sales_history_view; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.sales_history_view IS 'Vista optimizada para Historial de Ventas. Centraliza lógica de presentación (financiamiento, métodos de pago) y pre-calcula joins. Mantiene compatibilidad con funciones existentes (delete_sale_and_restore_inventory).';


