-- Name: COLUMN sales_history_view.id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sales_history_view.id IS 'UUID de la venta. CRÍTICO: Usado por handleConfirmDelete para eliminar ventas.';


--
-- Name: COLUMN sales_history_view.financing_type; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sales_history_view.financing_type IS 'Tipo de financiamiento: CASHEA, KRECE, o CONTADO';


--
-- Name: COLUMN sales_history_view.financing_label; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sales_history_view.financing_label IS 'Etiqueta completa para mostrar en badges: CASHEA, KRECE, o DE CONTADO';


--
-- Name: COLUMN sales_history_view.payment_method_label; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sales_history_view.payment_method_label IS 'Etiqueta traducida del método de pago para mostrar en UI';


--
-- Name: system_settings; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.system_settings (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    tax_rate numeric(5,2) DEFAULT 16.00 NOT NULL,
    currency character varying(3) DEFAULT 'USD'::character varying NOT NULL,
    timezone character varying(50) DEFAULT 'America/Caracas'::character varying NOT NULL,
    language character varying(2) DEFAULT 'es'::character varying NOT NULL,
    auto_backup boolean DEFAULT true NOT NULL,
    notifications_enabled boolean DEFAULT true NOT NULL,
    receipt_footer text DEFAULT 'Gracias por su compra'::text,
    barcode_prefix character varying(10) DEFAULT 'POS'::character varying,
    low_stock_threshold integer DEFAULT 10 NOT NULL,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    web_adjustment_rate numeric(10,4) DEFAULT NULL::numeric,
    web_tax_percentage numeric(5,2) DEFAULT 0.00,
    manual_bcv_rate numeric(12,4) DEFAULT NULL::numeric,
    web_adjustment_method text DEFAULT 'RATE'::text,
    CONSTRAINT system_settings_web_adjustment_method_check CHECK ((web_adjustment_method = ANY (ARRAY['RATE'::text, 'PERCENTAGE'::text])))
);


--
-- Name: COLUMN system_settings.web_adjustment_rate; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.system_settings.web_adjustment_rate IS 'Tasa administrativa para inflado web (ej. 50).';


--
-- Name: COLUMN system_settings.web_tax_percentage; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.system_settings.web_tax_percentage IS 'Recargo porcentual extra para precio web (ej. 5 = 5%).';


--
-- Name: COLUMN system_settings.manual_bcv_rate; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.system_settings.manual_bcv_rate IS 'Tasa BCV oficial (la que ve el público, ej. 40).';


--
-- Name: COLUMN system_settings.web_adjustment_method; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.system_settings.web_adjustment_method IS 'Método de ajuste: RATE=tasa inversa, PERCENTAGE=porcentaje. Solo uno aplica.';


--
-- Name: web_product_metadata; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.web_product_metadata (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    product_id uuid NOT NULL,
    image_url text,
    visible boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: TABLE web_product_metadata; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.web_product_metadata IS 'Metadatos específicos para catálogo web público. Incluye imagen y visibilidad.';


--
-- Name: COLUMN web_product_metadata.image_url; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.web_product_metadata.image_url IS 'URL de la imagen del producto para mostrar en la web pública';


--
-- Name: COLUMN web_product_metadata.visible; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.web_product_metadata.visible IS 'Si el producto es visible en el catálogo web público (true) o está oculto (false)';


--
-- Name: web_products_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.web_products_view AS
 SELECT p.id,
    p.company_id,
    p.sku,
    p.barcode,
    p.name,
    p.category,
    p.sale_price_usd,
    p.tax_rate,
    p.active,
    p.created_at,
    p.updated_at,
    wpm.image_url AS web_image_url,
    COALESCE(wpm.visible, true) AS web_visible
   FROM (public.products p
     LEFT JOIN public.web_product_metadata wpm ON ((p.id = wpm.product_id)))
  WHERE (p.active = true);


--
-- Name: VIEW web_products_view; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.web_products_view IS 'Vista pública para catálogo web. EXCLUYE cost_usd y otros datos sensibles. 
Solo productos activos. Incluye metadatos web (imagen, visibilidad).';


