--
-- Name: inventories inventory_activity_trigger; Type: TRIGGER; Schema: public; Owner: -
--

CREATE TRIGGER inventory_activity_trigger AFTER INSERT OR DELETE OR UPDATE ON public.inventories FOR EACH ROW EXECUTE FUNCTION public.log_inventory_activity();


--
-- Name: stores on_store_created; Type: TRIGGER; Schema: public; Owner: -
--

CREATE TRIGGER on_store_created AFTER INSERT ON public.stores FOR EACH ROW EXECUTE FUNCTION public.initialize_inventories_for_new_store();


--
-- Name: products product_activity_trigger; Type: TRIGGER; Schema: public; Owner: -
--

CREATE TRIGGER product_activity_trigger AFTER INSERT OR DELETE OR UPDATE ON public.products FOR EACH ROW EXECUTE FUNCTION public.log_product_activity();


--
-- Name: inventories trg_audit_inventory_change; Type: TRIGGER; Schema: public; Owner: -
--

CREATE TRIGGER trg_audit_inventory_change AFTER UPDATE ON public.inventories FOR EACH ROW WHEN ((old.qty IS DISTINCT FROM new.qty)) EXECUTE FUNCTION public.audit_inventory_change();


--
-- Name: TRIGGER trg_audit_inventory_change ON inventories; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TRIGGER trg_audit_inventory_change ON public.inventories IS 'Auditoría automática: inserta en inventory_movements con old_qty/new_qty cuando cambia qty.';


